    ('31678240-aedf-5b45-8120-15b60a3f7629'::uuid, 'Quiz — Les mêmes atomes ici et dans les étoiles', 'Physique-Chimie', '3e', 'La continuité de la matière dans l’Univers', '88eeedeb-5ca5-5463-a0da-5dd779723e54'::uuid),
