    ('26a174af-44f0-5be4-b697-2737d306e481'::uuid, 'Quiz — Décrire un mouvement, et par rapport à quoi', 'Physique-Chimie', '3e', 'Les mouvements', 'f4e93074-7692-578b-baa2-bae3a8d5e316'::uuid),
