    ('226fd74e-8407-5edc-8e42-5fa611ed97d5'::uuid, 'Quiz — La force qui tient les planètes et fait tomber les pommes', 'Physique-Chimie', '3e', 'Poids et gravitation', '8e65684a-04f9-5936-aed1-d8c1d16fac0f'::uuid),
