    ('1d2ee836-c30e-5104-b473-c7769734f204'::uuid, 'Quiz — L’énergie change de forme et change de lieu', 'Physique-Chimie', '3e', 'Transferts et conversions d’énergie', 'dec774a0-a578-5161-88bb-aa30ce9db682'::uuid),
    ('8a175c42-9ca5-5652-912c-ba838286c6b7'::uuid, 'Quiz — Pourquoi doubler la vitesse quadruple le danger', 'Physique-Chimie', '3e', 'Calculer la vitesse et l’énergie cinétique', 'cd11580e-09de-529e-8b05-24ebb5ed18ef'::uuid),
    ('2f109b8f-81b9-5c70-ac50-537a7dfb85a3'::uuid, 'Quiz — Rien ne se perd, mais tout se dégrade', 'Physique-Chimie', '3e', 'Conservation et pertes d’énergie', '2755148c-1bc6-5ae0-ba36-be8564bd5811'::uuid),
    ('1f6fa480-57ea-5c2f-b14e-edc709315925'::uuid, 'Quiz — Un déplacement de charges dans une boucle fermée', 'Physique-Chimie', '3e', 'Le courant électrique', '68a677a4-fc61-5c67-a8db-e68f68f570d8'::uuid),
    ('f9d5c161-34f0-5249-9ebb-d8f03e5b15ef'::uuid, 'Quiz — En série ou en dérivation : deux façons de brancher', 'Physique-Chimie', '3e', 'Les montages électriques', '391d58a7-1a64-51bd-b69a-5562ace858b9'::uuid),
    ('e600d2f2-d2d5-533d-a595-cb545436aa10'::uuid, 'Quiz — Ce que mesure un voltmètre', 'Physique-Chimie', '3e', 'La tension électrique', '0150a606-921c-5284-a93d-72095ba8c264'::uuid),
    ('bd683e3d-650d-5e95-a5f2-8a9e51bd159c'::uuid, 'Quiz — Le débit du courant', 'Physique-Chimie', '3e', 'L’intensité électrique', 'efb0fd47-6eca-5ac7-9c58-f5c98f4df3c9'::uuid),
    ('1b2c92c6-40c5-5fdc-a164-74ee78306a1b'::uuid, 'Quiz — La loi d’Ohm et l’effet Joule', 'Physique-Chimie', '3e', 'La résistance électrique', '826195fb-9ca3-5f03-a34a-801732923e0b'::uuid),
    ('d29dd555-f284-587b-a4b6-ad636363deef'::uuid, 'Quiz — Ce qui consomme, et ce que ça coûte', 'Physique-Chimie', '3e', 'Puissance et énergie électrique', '68ebdf1c-c3d5-5945-9ab3-cb566fcec6eb'::uuid),
    ('9e11b9ff-61bd-5a6f-940d-cbe0b2276a5d'::uuid, 'Quiz — Transporter une information sans transporter de matière', 'Physique-Chimie', '3e', 'Signal et information', 'c4d69cf9-3e83-591a-bf41-2e9c16016f87'::uuid),
    ('e0a19e09-b987-5025-bd20-6c4f00eeb94e'::uuid, 'Quiz — Sources, propagation, couleurs', 'Physique-Chimie', '3e', 'La lumière', 'd95f5a80-707e-513b-98d3-68048005ce4a'::uuid),
    ('1b8b8546-2565-55c6-ba12-7a419b5d728b'::uuid, 'Quiz — Une vibration qui a besoin de matière', 'Physique-Chimie', '3e', 'Le son', '75683cdc-3820-5158-8aa5-5f4564214ebf'::uuid),
    ('0a5510c5-38df-57c7-84c2-07feb5862f56'::uuid, 'Quiz — Lire un son sur un écran', 'Physique-Chimie', '3e', 'Les signaux sonores', '97bc9a08-a526-51f4-a4de-5589cc74adf7'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('5f19396c-7615-59af-a96f-53277f04a7d4'::uuid, '32332cb8-d8df-5a40-b55c-28ea7b39be54'::uuid, 'Qu’est-ce qu’un corps pur ?', 'mcq', '["Un corps constitué d’une seule espèce chimique","Un corps sans couleur","Un corps qui ne réagit avec rien","Un corps toujours solide"]'::jsonb, 0, 'L’eau distillée, le fer ou le dioxygène en sont.', 1),
    ('f55110ee-9ffc-57cf-91a4-b5ed3d446f81'::uuid, '32332cb8-d8df-5a40-b55c-28ea7b39be54'::uuid, 'Comment reconnaît-on un mélange homogène ?', 'mcq', '["On ne distingue pas ses constituants, même après repos","Il est toujours transparent et incolore","Il se sépare par filtration","Il contient toujours de l’eau"]'::jsonb, 0, 'L’eau salée et l’air en sont des exemples.', 2),
    ('f32324b2-2ade-5eb6-96b9-e018d9f9acd8'::uuid, '32332cb8-d8df-5a40-b55c-28ea7b39be54'::uuid, 'Quelle technique sépare l’eau et le sable ?', 'mcq', '["La filtration","La distillation","La chromatographie","L’électrolyse"]'::jsonb, 0, 'Le sable est insoluble : le filtre le retient.', 3),
    ('a6cfad94-ec36-51c7-bf4c-d5510a000c29'::uuid, '32332cb8-d8df-5a40-b55c-28ea7b39be54'::uuid, 'Quelle technique permet de récupérer l’eau pure d’une eau salée ?', 'mcq', '["La distillation","La filtration","La décantation","Le tamisage"]'::jsonb, 0, 'Le sel dissous traverse tous les filtres.', 4),
    ('36ee6232-e545-5288-992f-81914180ee18'::uuid, '32332cb8-d8df-5a40-b55c-28ea7b39be54'::uuid, 'Comment appelle-t-on le liquide obtenu après une filtration ?', 'mcq', '["Le filtrat","Le distillat","Le résidu","Le solvant"]'::jsonb, 0, 'Le distillat, lui, est le produit d’une distillation.', 5),
    ('44125b09-3c4f-547c-8433-826e66e8a72c'::uuid, '32332cb8-d8df-5a40-b55c-28ea7b39be54'::uuid, 'Quel test permet de détecter la présence d’eau ?', 'mcq', '["Le sulfate de cuivre anhydre, qui passe du blanc au bleu","L’eau de chaux, qui se trouble","La bûchette incandescente","Le papier pH"]'::jsonb, 0, 'C’est le test caractéristique de l’eau.', 6),
    ('d50b17a3-a725-5094-bb35-932dcfe4f2f4'::uuid, '32332cb8-d8df-5a40-b55c-28ea7b39be54'::uuid, 'Comment un corps pur se comporte-t-il pendant un changement d’état ?', 'mcq', '["Sa température reste constante","Sa température augmente régulièrement","Sa masse diminue","Il change de couleur"]'::jsonb, 0, 'Un mélange, lui, change d’état sur un intervalle de températures.', 7),
    ('c415ee28-03d1-55f9-8f82-3c8443bf0731'::uuid, '32332cb8-d8df-5a40-b55c-28ea7b39be54'::uuid, 'La filtration permet de séparer les constituants d’un mélange homogène.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle ne retient que ce qui n’est pas dissous.', 8),
    ('8c571394-f78e-57a7-bec0-d5cb2809da43'::uuid, '22a06e67-d931-5934-b162-35b3777d537d'::uuid, 'Quel état a un volume propre mais pas de forme propre ?', 'mcq', '["L’état liquide","L’état solide","L’état gazeux","Aucun"]'::jsonb, 0, 'Le liquide prend la forme du récipient sans changer de volume.', 1),
    ('14a90c2f-117c-50d1-9790-aeeae3b25bb1'::uuid, '22a06e67-d931-5934-b162-35b3777d537d'::uuid, 'Comment sont les molécules dans un gaz ?', 'mcq', '["Très éloignées, désordonnées et très agitées","Serrées et ordonnées","Serrées et immobiles","Alignées en rangées régulières"]'::jsonb, 0, 'C’est le vide entre elles qui rend le gaz compressible.', 2),
    ('b8704523-ce79-589f-a140-a5369f9fc670'::uuid, '22a06e67-d931-5934-b162-35b3777d537d'::uuid, 'Pourquoi un gaz est-il compressible ?', 'mcq', '["Parce que ses molécules sont très éloignées les unes des autres","Parce que ses molécules sont plus petites","Parce qu’il est plus léger que l’air","Parce qu’il n’a pas de masse"]'::jsonb, 0, 'On peut réduire son volume en rapprochant les molécules.', 3),
    ('21fbb4cf-57f2-55ae-8117-f3fbabe53013'::uuid, '22a06e67-d931-5934-b162-35b3777d537d'::uuid, 'Que devient la masse lors d’un changement d’état ?', 'mcq', '["Elle se conserve","Elle augmente","Elle diminue","Elle devient nulle"]'::jsonb, 0, 'Les molécules sont les mêmes, seule leur organisation change.', 4),
    ('a1855b3d-bd0f-5a2c-8903-a44bd2fe92cb'::uuid, '22a06e67-d931-5934-b162-35b3777d537d'::uuid, 'Que fait le volume de l’eau quand elle gèle ?', 'mcq', '["Il augmente","Il diminue","Il reste identique","Il devient nul"]'::jsonb, 0, 'C’est une exception : une bouteille pleine peut éclater au congélateur.', 5),
    ('ec7a1048-b6fa-5003-9e49-f7ff0e79f554'::uuid, '22a06e67-d931-5934-b162-35b3777d537d'::uuid, 'Comment sont les molécules dans un solide cristallin ?', 'mcq', '["Serrées, ordonnées et vibrant sur place","Éloignées et immobiles","Serrées et glissant les unes sur les autres","Réparties au hasard et très agitées"]'::jsonb, 0, 'L’ordre distingue un solide cristallin d’un solide amorphe.', 6),
    ('e7f9a8f2-81ab-5f72-a209-89a2d16432b2'::uuid, '22a06e67-d931-5934-b162-35b3777d537d'::uuid, 'Que se passe-t-il quand la température augmente ?', 'mcq', '["L’agitation des molécules augmente","Les molécules deviennent plus grosses","Le nombre de molécules augmente","Les molécules changent de nature"]'::jsonb, 0, 'C’est l’agitation thermique.', 7),
    ('a2b97ae1-a5bc-529b-bd86-8733bafe71be'::uuid, '22a06e67-d931-5934-b162-35b3777d537d'::uuid, 'Un liquide occupe tout le volume du récipient qui le contient.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est le gaz qui est expansible ; le liquide garde son volume.', 8),
    ('3bfe2353-e6ed-5b95-9b71-7fdcf3bafc1e'::uuid, 'f36b3f25-2788-59d0-8133-8022efaa0c13'::uuid, 'Comment appelle-t-on le passage de l’état solide à l’état liquide ?', 'mcq', '["La fusion","La solidification","La sublimation","La liquéfaction"]'::jsonb, 0, 'Le passage inverse est la solidification.', 1),
    ('3791ab25-380d-5ac7-868c-a4863d26ab97'::uuid, 'f36b3f25-2788-59d0-8133-8022efaa0c13'::uuid, 'Comment appelle-t-on le passage de l’état gazeux à l’état liquide ?', 'mcq', '["La liquéfaction","La vaporisation","La sublimation","La fusion"]'::jsonb, 0, 'C’est ce qui produit la buée sur une vitre froide.', 2),
    ('6e3aeb66-df71-5c16-9f72-e65fb9c7b7c8'::uuid, 'f36b3f25-2788-59d0-8133-8022efaa0c13'::uuid, 'Comment appelle-t-on le passage direct de l’état solide à l’état gazeux ?', 'mcq', '["La sublimation","La fusion","L’évaporation","La condensation solide"]'::jsonb, 0, 'Le passage inverse est la condensation solide.', 3),
    ('4d4dc4d3-3f26-5cda-b702-a2345e1cccbe'::uuid, 'f36b3f25-2788-59d0-8133-8022efaa0c13'::uuid, 'À quelle température l’eau pure fond-elle sous pression normale ?', 'mcq', '["0 °C","100 °C","−10 °C","37 °C"]'::jsonb, 0, 'C’est aussi sa température de solidification.', 4),
    ('2f7b0241-f23c-5562-b621-19c0f0826a5a'::uuid, 'f36b3f25-2788-59d0-8133-8022efaa0c13'::uuid, 'Que fait la température pendant le changement d’état d’un corps pur ?', 'mcq', '["Elle reste constante","Elle augmente régulièrement","Elle chute brutalement","Elle oscille"]'::jsonb, 0, 'Ce palier est la signature d’un corps pur.', 5),
    ('5e878864-d24f-5a08-aacd-2b78b1cb2415'::uuid, 'f36b3f25-2788-59d0-8133-8022efaa0c13'::uuid, 'Quel est l’effet du sel sur la température de fusion de l’eau ?', 'mcq', '["Il l’abaisse en dessous de 0 °C","Il l’élève au-dessus de 0 °C","Il ne change rien","Il empêche toute fusion"]'::jsonb, 0, 'C’est le principe du salage des routes en hiver.', 6),
    ('3e2c5be0-d1de-5087-ab94-876eba34b707'::uuid, 'f36b3f25-2788-59d0-8133-8022efaa0c13'::uuid, 'Pourquoi l’eau bout-elle en dessous de 100 °C en altitude ?', 'mcq', '["Parce que la pression atmosphérique y est plus faible","Parce que l’air y est plus froid","Parce que l’eau y est moins pure","Parce que le soleil y est plus fort"]'::jsonb, 0, 'La température d’ébullition dépend de la pression.', 7),
    ('4d595595-be0a-51e6-848f-6f43b3b317a1'::uuid, 'f36b3f25-2788-59d0-8133-8022efaa0c13'::uuid, 'La vapeur d’eau est le nuage blanc que l’on voit au-dessus d’une casserole.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La vapeur d’eau est invisible : le nuage blanc est fait de gouttelettes liquides.', 8),
    ('8b555cd0-a367-5dee-869a-abbd7d6c42db'::uuid, '3969be60-b1ca-558f-b348-a35f72365c01'::uuid, 'Que signifie « deux liquides sont miscibles » ?', 'mcq', '["Ils forment un mélange homogène","Ils forment deux couches distinctes","Ils réagissent chimiquement","Ils ont la même masse volumique"]'::jsonb, 0, 'L’eau et l’alcool sont miscibles, l’eau et l’huile non.', 1),
    ('a8944274-79de-5a1d-9da7-4f6a6713e7d8'::uuid, '3969be60-b1ca-558f-b348-a35f72365c01'::uuid, 'Dans un mélange d’eau et d’huile, où se place l’huile ?', 'mcq', '["Au-dessus, car elle est moins dense","En dessous, car elle est plus dense","Au milieu","Elle se dissout entièrement"]'::jsonb, 0, 'Le liquide le moins dense surnage.', 2),
    ('4602fce9-dcb3-5ff9-abf3-11f2ee331073'::uuid, '3969be60-b1ca-558f-b348-a35f72365c01'::uuid, 'Quel matériel sépare deux liquides non miscibles ?', 'mcq', '["L’ampoule à décanter","Le filtre à café","Le réfrigérant","La burette graduée"]'::jsonb, 0, 'On soutire la phase du bas par le robinet.', 3),
    ('2a25472b-d973-564c-bfd7-3c53da4bc3b1'::uuid, '3969be60-b1ca-558f-b348-a35f72365c01'::uuid, 'Dans une dissolution, comment appelle-t-on l’espèce dissoute ?', 'mcq', '["Le soluté","Le solvant","Le filtrat","Le précipité"]'::jsonb, 0, 'Le solvant est le liquide qui dissout.', 4),
    ('3310b66e-65a0-5a55-b48b-cf87baf8dfe5'::uuid, '3969be60-b1ca-558f-b348-a35f72365c01'::uuid, 'Que devient la masse lors d’une dissolution ?', 'mcq', '["Elle se conserve","Elle diminue","Elle augmente","Elle devient nulle"]'::jsonb, 0, 'Masse de la solution = masse du solvant + masse du soluté.', 5),
    ('1eb3c89e-9ead-5c4b-b253-1979c405f93d'::uuid, '3969be60-b1ca-558f-b348-a35f72365c01'::uuid, 'Qu’est-ce qu’une solution saturée ?', 'mcq', '["Une solution qui ne peut plus dissoudre de soluté","Une solution trop diluée","Une solution colorée","Une solution chauffée"]'::jsonb, 0, 'Le surplus de soluté reste au fond.', 6),
    ('ec0a938d-0400-52f9-92db-cf9b2fd804af'::uuid, '3969be60-b1ca-558f-b348-a35f72365c01'::uuid, 'Comment évolue la solubilité d’un gaz quand la température augmente ?', 'mcq', '["Elle diminue","Elle augmente","Elle ne change pas","Elle devient infinie"]'::jsonb, 0, 'C’est pourquoi un soda tiède pétille moins et pourquoi l’eau chaude contient moins de dioxygène.', 7),
    ('2baf39fd-7e1d-519b-b330-a5d310bd5b22'::uuid, '3969be60-b1ca-558f-b348-a35f72365c01'::uuid, 'Le sucre dissous dans l’eau a disparu.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est dispersé en particules invisibles : la masse totale le prouve.', 8),
    ('67fee03a-40c4-5a75-a4f9-5550f3b5e206'::uuid, '2e47978c-fb6e-5268-99ee-e0218aac3ecd'::uuid, 'Quelle est la proportion de diazote dans l’air ?', 'mcq', '["Environ 78 %","Environ 21 %","Environ 50 %","Environ 1 %"]'::jsonb, 0, 'Le dioxygène ne représente qu’environ 21 %.', 1),
    ('12c144e5-bf8b-5966-a9cd-93613bce4213'::uuid, '2e47978c-fb6e-5268-99ee-e0218aac3ecd'::uuid, 'Quel gaz représente environ 21 % de l’air ?', 'mcq', '["Le dioxygène","Le diazote","Le dioxyde de carbone","L’argon"]'::jsonb, 0, 'C’est celui que nous consommons en respirant.', 2),
    ('459c25b0-22b7-5881-b00a-eed196ea89d8'::uuid, '2e47978c-fb6e-5268-99ee-e0218aac3ecd'::uuid, 'Quel test identifie le dioxygène ?', 'mcq', '["La bûchette incandescente, qui se rallume","L’eau de chaux, qui se trouble","Le sulfate de cuivre anhydre, qui bleuit","Le papier pH, qui rougit"]'::jsonb, 0, 'L’eau de chaux sert, elle, à détecter le dioxyde de carbone.', 3),
    ('edeb9b3b-ccf5-568f-9d83-bc8f18e864ab'::uuid, '2e47978c-fb6e-5268-99ee-e0218aac3ecd'::uuid, 'Quel test identifie le dioxyde de carbone ?', 'mcq', '["L’eau de chaux, qui se trouble","La bûchette incandescente","Le sulfate de cuivre anhydre","Le test à la flamme"]'::jsonb, 0, 'L’eau de chaux devient blanche laiteuse.', 4),
    ('d6fa10f8-abfa-53f1-83ee-bb34d1726bd6'::uuid, '2e47978c-fb6e-5268-99ee-e0218aac3ecd'::uuid, 'Quelle est environ la masse d’un litre d’air ?', 'mcq', '["1,2 g","1,2 kg","12 g","Elle est nulle"]'::jsonb, 0, 'On le vérifie en pesant un ballon gonflé puis dégonflé.', 5),
    ('01c03e6f-60c0-5b86-bef5-54698ca65573'::uuid, '2e47978c-fb6e-5268-99ee-e0218aac3ecd'::uuid, 'Dans quelle unité mesure-t-on la pression atmosphérique ?', 'mcq', '["L’hectopascal (hPa)","Le newton (N)","Le joule (J)","Le watt (W)"]'::jsonb, 0, 'Environ 1 013 hPa au niveau de la mer.', 6),
    ('12b9caef-95b2-5d39-a259-57818807f6ef'::uuid, '2e47978c-fb6e-5268-99ee-e0218aac3ecd'::uuid, 'Comment évolue la pression atmosphérique avec l’altitude ?', 'mcq', '["Elle diminue","Elle augmente","Elle reste constante","Elle s’annule à 1 000 m"]'::jsonb, 0, 'La colonne d’air au-dessus est plus courte.', 7),
    ('b12b1b77-0dc4-52d5-b60c-c5d331074184'::uuid, '2e47978c-fb6e-5268-99ee-e0218aac3ecd'::uuid, 'L’air est un corps pur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un mélange homogène de plusieurs gaz.', 8),
    ('a8ed2430-bf35-5239-bf3a-a8fd76989dfc'::uuid, '30d97e7f-dc68-5f3f-84d7-5cb83f040f7e'::uuid, 'Quelle est la formule de la masse volumique ?', 'mcq', '["ρ = m ÷ V","ρ = V ÷ m","ρ = m × V","ρ = m + V"]'::jsonb, 0, 'La masse divisée par le volume occupé.', 1),
    ('e43bbf95-49af-5718-8a08-17db5cf07c51'::uuid, '30d97e7f-dc68-5f3f-84d7-5cb83f040f7e'::uuid, 'Quelle est la masse volumique de l’eau ?', 'mcq', '["1 g/cm³","10 g/cm³","0,1 g/cm³","1 000 g/cm³"]'::jsonb, 0, 'Soit 1 000 kg/m³ : les deux écritures désignent la même valeur.', 2),
    ('65b6a7ef-c8a1-5c3d-ba56-63545cd0e7b3'::uuid, '30d97e7f-dc68-5f3f-84d7-5cb83f040f7e'::uuid, 'À quelle condition un corps flotte-t-il sur un liquide ?', 'mcq', '["Si sa masse volumique est inférieure à celle du liquide","Si sa masse est inférieure à celle du liquide","S’il est creux","Si son volume est supérieur à celui du liquide"]'::jsonb, 0, 'C’est pourquoi l’huile surnage sur l’eau.', 3),
    ('8fc836c9-02b8-5af9-a4e9-0f465f16b116'::uuid, '30d97e7f-dc68-5f3f-84d7-5cb83f040f7e'::uuid, 'Comment mesure-t-on le volume d’un objet de forme irrégulière ?', 'mcq', '["Par le volume d’eau qu’il déplace dans une éprouvette graduée","En le pesant","En mesurant sa plus grande longueur","En le chauffant"]'::jsonb, 0, 'C’est la méthode par déplacement d’eau.', 4),
    ('6ff2126f-a77e-50b6-9aab-ba0b4db3bc4b'::uuid, '30d97e7f-dc68-5f3f-84d7-5cb83f040f7e'::uuid, 'À combien de cm³ correspond 1 mL ?', 'mcq', '["1 cm³","10 cm³","100 cm³","0,1 cm³"]'::jsonb, 0, 'Et 1 L = 1 dm³ = 1 000 cm³.', 5),
    ('fd56ce1e-6c1c-5524-a575-95b835d3440a'::uuid, '30d97e7f-dc68-5f3f-84d7-5cb83f040f7e'::uuid, 'Un objet de 79 g occupe 10 cm³. Quel est ce matériau probable ?', 'mcq', '["Le fer, de masse volumique 7,9 g/cm³","L’eau","L’huile","L’air"]'::jsonb, 0, 'ρ = 79 ÷ 10 = 7,9 g/cm³.', 6),
    ('d325036a-fa1d-56fa-a776-d74392ec2d15'::uuid, '30d97e7f-dc68-5f3f-84d7-5cb83f040f7e'::uuid, 'À combien de kg/m³ correspond 1 g/cm³ ?', 'mcq', '["1 000 kg/m³","1 kg/m³","100 kg/m³","10 000 kg/m³"]'::jsonb, 0, 'La conversion est un piège classique du chapitre.', 7),
    ('40fa80ea-2f22-5541-896c-919810bb62c0'::uuid, '30d97e7f-dc68-5f3f-84d7-5cb83f040f7e'::uuid, 'Deux objets de même masse ont forcément la même masse volumique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Encore faut-il qu’ils aient le même volume : un kilo de plumes n’occupe pas le volume d’un kilo de plomb.', 8),
    ('870bc4b0-71fb-5c4d-9f63-1d3042f29b07'::uuid, '6c9da2d9-7931-5eba-bd2e-67bc5d78f7c2'::uuid, 'Comment appelle-t-on les espèces qui disparaissent au cours d’une transformation chimique ?', 'mcq', '["Les réactifs","Les produits","Les catalyseurs","Les solutés"]'::jsonb, 0, 'Celles qui apparaissent sont les produits.', 1),
    ('447254dd-04e9-53a9-80c4-ce3294fff702'::uuid, '6c9da2d9-7931-5eba-bd2e-67bc5d78f7c2'::uuid, 'Quelle différence y a-t-il entre un changement d’état et une transformation chimique ?', 'mcq', '["Le changement d’état ne modifie pas les molécules, la transformation chimique les réorganise","Le changement d’état dégage toujours de la chaleur","La transformation chimique est réversible, pas le changement d’état","Il n’y a aucune différence"]'::jsonb, 0, 'La glace qui fond reste de l’eau ; le bois qui brûle n’est plus du bois.', 2),
    ('91f55323-b7de-5baa-bbbb-bee1fb254944'::uuid, '6c9da2d9-7931-5eba-bd2e-67bc5d78f7c2'::uuid, 'Que devient la masse totale au cours d’une transformation chimique ?', 'mcq', '["Elle se conserve","Elle augmente","Elle diminue","Elle double"]'::jsonb, 0, 'C’est la loi de Lavoisier : les atomes sont réarrangés, pas créés.', 3),
    ('cbe04a46-2c61-56bb-9d35-56e8751d5990'::uuid, '6c9da2d9-7931-5eba-bd2e-67bc5d78f7c2'::uuid, 'Que signifie la flèche dans une équation de réaction ?', 'mcq', '["Elle sépare les réactifs des produits","Elle indique une addition","Elle signifie « est égal à »","Elle indique un chauffage"]'::jsonb, 0, 'Elle se lit « donne » ou « réagit pour former ».', 4),
    ('8b819c49-f42b-5d0c-bdcb-279cfe7cbe2c'::uuid, '6c9da2d9-7931-5eba-bd2e-67bc5d78f7c2'::uuid, 'À quoi servent les nombres écrits devant les formules chimiques ?', 'mcq', '["À ajuster l’équation pour conserver les atomes","À indiquer la température","À donner la masse des espèces","À numéroter les étapes"]'::jsonb, 0, 'Ce sont les nombres stœchiométriques.', 5),
    ('fafcff1d-1343-562c-8fbf-ff98d8f93675'::uuid, '6c9da2d9-7931-5eba-bd2e-67bc5d78f7c2'::uuid, 'Quelle est l’équation ajustée de la combustion du méthane ?', 'mcq', '["CH₄ + 2 O₂ → CO₂ + 2 H₂O","CH₄ + O₂ → CO₂ + H₂O","CH₄ + 2 O₂ → CO₂ + H₂O","CH₄ + O₂ → CO₂ + 2 H₂O"]'::jsonb, 0, 'Quatre atomes d’hydrogène à gauche exigent deux molécules d’eau à droite.', 6),
    ('3e9df0b4-45c6-5116-b609-c6a38f822b44'::uuid, '6c9da2d9-7931-5eba-bd2e-67bc5d78f7c2'::uuid, 'Qu’est-ce que le réactif limitant ?', 'mcq', '["Le réactif entièrement consommé, qui arrête la réaction","Le réactif le plus abondant","Le réactif le plus dangereux","Le réactif qui reste à la fin"]'::jsonb, 0, 'C’est lui qui fixe la quantité de produits formés.', 7),
    ('cb3ba874-421c-52f0-97b8-b4e9671e2ce8'::uuid, '6c9da2d9-7931-5eba-bd2e-67bc5d78f7c2'::uuid, 'Au cours d’une transformation chimique, des atomes peuvent être créés.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils sont seulement réarrangés : c’est pourquoi la masse se conserve.', 8),
    ('14c83654-5d80-5390-9f0d-5b11596cd15a'::uuid, 'dffa816d-a78c-5ed5-b264-d478cbf6bbca'::uuid, 'Quel test identifie le dihydrogène ?', 'mcq', '["Une détonation à l’approche d’une flamme","L’eau de chaux qui se trouble","La bûchette qui se rallume","Le sulfate de cuivre qui bleuit"]'::jsonb, 0, 'On l’appelle familièrement le test de l’aboiement.', 1),
    ('12c0df2d-6d84-5fba-be05-ae9f5e122250'::uuid, 'dffa816d-a78c-5ed5-b264-d478cbf6bbca'::uuid, 'Quel précipité obtient-on en ajoutant de la soude à une solution d’ions cuivre II ?', 'mcq', '["Un précipité bleu","Un précipité vert","Un précipité rouille","Un précipité blanc"]'::jsonb, 0, 'Le vert signale les ions fer II, le rouille les ions fer III.', 2),
    ('de33417b-a37c-5ae4-b71b-650c67bcdf7c'::uuid, 'dffa816d-a78c-5ed5-b264-d478cbf6bbca'::uuid, 'Quel précipité signale la présence d’ions fer III ?', 'mcq', '["Un précipité rouille","Un précipité bleu","Un précipité vert","Un précipité noir"]'::jsonb, 0, 'Les ions fer II donnent, eux, un précipité vert.', 3),
    ('0ec1d3f3-9872-5fda-81f7-b0f7f2d84df1'::uuid, 'dffa816d-a78c-5ed5-b264-d478cbf6bbca'::uuid, 'Quel réactif identifie les ions chlorure ?', 'mcq', '["Le nitrate d’argent","La soude","L’eau de chaux","Le sulfate de cuivre anhydre"]'::jsonb, 0, 'Il forme un précipité blanc qui noircit à la lumière.', 4),
    ('abd7ce87-2e6d-5a5c-9049-e6f3949911ee'::uuid, 'dffa816d-a78c-5ed5-b264-d478cbf6bbca'::uuid, 'Que devient le sulfate de cuivre anhydre en présence d’eau ?', 'mcq', '["Il passe du blanc au bleu","Il passe du bleu au blanc","Il devient vert","Il ne change pas"]'::jsonb, 0, 'C’est le test caractéristique de l’eau.', 5),
    ('edca2923-0ff5-5ff7-ba68-1fccc14ebfda'::uuid, 'dffa816d-a78c-5ed5-b264-d478cbf6bbca'::uuid, 'Quel précipité obtient-on avec les ions zinc et la soude ?', 'mcq', '["Un précipité blanc","Un précipité bleu","Un précipité vert","Aucun précipité"]'::jsonb, 0, 'Il ne faut pas le confondre avec le précipité blanc des ions chlorure, obtenu avec un autre réactif.', 6),
    ('d9b945b6-e166-5c1e-884b-d9891a0fba85'::uuid, 'dffa816d-a78c-5ed5-b264-d478cbf6bbca'::uuid, 'Comment doit-on conclure un test caractéristique ?', 'mcq', '["En nommant l’espèce chimique identifiée","En donnant la couleur observée","En indiquant le volume utilisé","En mesurant la température"]'::jsonb, 0, '« Précipité bleu » décrit ; « la solution contient des ions cuivre II » conclut.', 7),
    ('d3bc1dcd-d95a-5e79-b83c-31ca6fa1a37b'::uuid, 'dffa816d-a78c-5ed5-b264-d478cbf6bbca'::uuid, 'La soude peut être manipulée sans protection particulière.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est corrosive : lunettes, gants et blouse sont obligatoires.', 8),
    ('df4c2df6-4553-5663-a814-ffb1f845f700'::uuid, '311432ac-c34c-53e5-bd22-d1e8c41d4cce'::uuid, 'Qu’est-ce qu’un ion ?', 'mcq', '["Un atome qui a gagné ou perdu un ou plusieurs électrons","Un atome sans noyau","Un atome plus gros que la normale","Une molécule d’eau chargée"]'::jsonb, 0, 'Il porte de ce fait une charge électrique.', 1),
    ('d2510114-67c6-510e-8e4d-31c7e4fde3d8'::uuid, '311432ac-c34c-53e5-bd22-d1e8c41d4cce'::uuid, 'Comment appelle-t-on un ion chargé positivement ?', 'mcq', '["Un cation","Un anion","Un isotope","Un électron"]'::jsonb, 0, 'Il a perdu des électrons : Na⁺, Cu²⁺, Fe³⁺.', 2),
    ('008e41ca-ad23-5033-a063-e50975dec835'::uuid, '311432ac-c34c-53e5-bd22-d1e8c41d4cce'::uuid, 'Que signifie la notation Cu²⁺ ?', 'mcq', '["L’atome de cuivre a perdu deux électrons","L’atome de cuivre a gagné deux électrons","Il y a deux atomes de cuivre","Le cuivre a deux protons"]'::jsonb, 0, 'Le chiffre en exposant donne le nombre de charges.', 3),
    ('b3c3091d-1492-56ad-b143-737896a1fddf'::uuid, '311432ac-c34c-53e5-bd22-d1e8c41d4cce'::uuid, 'Que se passe-t-il quand un atome gagne un électron ?', 'mcq', '["Il devient un anion, chargé négativement","Il devient un cation","Il change d’élément chimique","Il perd son noyau"]'::jsonb, 0, 'Le noyau ne change jamais : l’élément reste le même.', 4),
    ('e363147a-0f2c-5f1f-bf4f-0fca83053f3a'::uuid, '311432ac-c34c-53e5-bd22-d1e8c41d4cce'::uuid, 'Quels ions obtient-on en dissolvant du sel dans l’eau ?', 'mcq', '["Des ions sodium Na⁺ et chlorure Cl⁻","Des ions cuivre et sulfate","Des ions hydrogène et hydroxyde","Des atomes de sodium et de chlore"]'::jsonb, 0, 'La solution reste électriquement neutre dans son ensemble.', 5),
    ('2816eae7-9a8a-5253-9435-51f52da95eb7'::uuid, '311432ac-c34c-53e5-bd22-d1e8c41d4cce'::uuid, 'Pourquoi une solution ionique conduit-elle le courant ?', 'mcq', '["Parce que les ions, mobiles, transportent la charge électrique","Parce que l’eau est un métal","Parce que les molécules d’eau se déplacent","Parce que la solution chauffe"]'::jsonb, 0, 'Dans un métal, ce sont les électrons libres qui jouent ce rôle.', 6),
    ('6c483731-b95e-5ace-8f7a-2332b56d8f14'::uuid, '311432ac-c34c-53e5-bd22-d1e8c41d4cce'::uuid, 'Quelle solution conduit le mieux le courant électrique ?', 'mcq', '["L’eau salée","L’eau distillée","L’huile","L’alcool pur"]'::jsonb, 0, 'Elle est riche en ions ; l’eau distillée en est presque dépourvue.', 7),
    ('572dd6f6-4c7b-5de9-8207-2d24c419dcda'::uuid, '311432ac-c34c-53e5-bd22-d1e8c41d4cce'::uuid, 'Une solution ionique porte une charge électrique globale.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est neutre : autant de charges positives que de négatives.', 8),
    ('44ea52ea-8aae-50ac-872e-d781d71f9ae0'::uuid, '148085c5-514f-586a-9fba-adfa25123d70'::uuid, 'Entre quelles valeurs le pH est-il compris en pratique ?', 'mcq', '["Entre 0 et 14","Entre 0 et 7","Entre 1 et 10","Entre −7 et 7"]'::jsonb, 0, 'Le pH n’a pas d’unité.', 1),
    ('e66d4cae-7625-5270-89fb-b380d3f2cb87'::uuid, '148085c5-514f-586a-9fba-adfa25123d70'::uuid, 'Quel est le pH d’une solution neutre ?', 'mcq', '["7","0","14","1"]'::jsonb, 0, 'C’est le pH de l’eau pure.', 2),
    ('e71a667d-5c3f-5830-ab96-945e15f991e8'::uuid, '148085c5-514f-586a-9fba-adfa25123d70'::uuid, 'Quels ions sont majoritaires dans une solution acide ?', 'mcq', '["Les ions hydrogène H⁺","Les ions hydroxyde OH⁻","Les ions chlorure Cl⁻","Les ions sodium Na⁺"]'::jsonb, 0, 'Dans une solution basique, ce sont les ions hydroxyde.', 3),
    ('e2b09754-00e4-5667-898a-bf0fe2dcf9bd'::uuid, '148085c5-514f-586a-9fba-adfa25123d70'::uuid, 'Quel appareil mesure le pH avec précision ?', 'mcq', '["Le pH-mètre","Le voltmètre","Le baromètre","Le thermomètre"]'::jsonb, 0, 'Le papier pH ne donne qu’une valeur approchée, à une unité près.', 4),
    ('3ea3a7de-5d4d-5397-970d-1dd2bfc0e6d4'::uuid, '148085c5-514f-586a-9fba-adfa25123d70'::uuid, 'Que devient le pH d’une solution acide que l’on dilue ?', 'mcq', '["Il augmente et se rapproche de 7","Il diminue","Il ne change pas","Il dépasse 7"]'::jsonb, 0, 'La concentration en ions H⁺ diminue sans changer de nature.', 5),
    ('87748a5a-f5e2-57ad-ae1e-15e61df69cab'::uuid, '148085c5-514f-586a-9fba-adfa25123d70'::uuid, 'Quelle solution a le pH le plus faible ?', 'mcq', '["Le jus de citron","L’eau pure","L’eau savonneuse","Le déboucheur"]'::jsonb, 0, 'Plus le pH est petit, plus la solution est acide.', 6),
    ('0a337e39-c42e-5341-baf4-daf2eb244513'::uuid, '148085c5-514f-586a-9fba-adfa25123d70'::uuid, 'Comment prépare-t-on une solution acide diluée en sécurité ?', 'mcq', '["On verse l’acide dans l’eau","On verse l’eau dans l’acide","On mélange les deux simultanément","On chauffe d’abord l’acide"]'::jsonb, 0, 'L’opération dégage de la chaleur et peut provoquer des projections.', 7),
    ('e2f1d7dd-10c7-5c0d-ad3f-13804244aa88'::uuid, '148085c5-514f-586a-9fba-adfa25123d70'::uuid, 'Diluer suffisamment une solution acide finit par la rendre basique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On s’approche de 7 sans jamais le dépasser.', 8),
    ('8d48bc41-7b97-52ce-954b-91e734645730'::uuid, 'da1a2441-a0f6-5ae8-96a9-da8eb6453c45'::uuid, 'Quel gaz se dégage quand l’acide chlorhydrique attaque le fer ?', 'mcq', '["Le dihydrogène","Le dioxygène","Le dioxyde de carbone","Le diazote"]'::jsonb, 0, 'On l’identifie par une détonation à l’approche d’une flamme.', 1),
    ('9a69fa9e-5eac-5240-8b07-65c217f09611'::uuid, 'da1a2441-a0f6-5ae8-96a9-da8eb6453c45'::uuid, 'Quelle couleur prend la solution après réaction de l’acide chlorhydrique avec le fer ?', 'mcq', '["Verte, à cause des ions fer II","Bleue, à cause des ions cuivre","Rouille, à cause des ions fer III","Elle reste incolore"]'::jsonb, 0, 'Un test à la soude donne un précipité vert.', 2),
    ('6de893a4-47f3-581b-b00f-5f6b769fc680'::uuid, 'da1a2441-a0f6-5ae8-96a9-da8eb6453c45'::uuid, 'Quels ions de l’acide réagissent réellement avec le métal ?', 'mcq', '["Les ions hydrogène H⁺","Les ions chlorure Cl⁻","Les ions hydroxyde OH⁻","Les ions sodium Na⁺"]'::jsonb, 0, 'Les ions chlorure sont des ions spectateurs.', 3),
    ('a287e236-0604-58aa-8b28-309a4b7b680c'::uuid, 'da1a2441-a0f6-5ae8-96a9-da8eb6453c45'::uuid, 'Quel métal ne réagit pas avec l’acide chlorhydrique ?', 'mcq', '["Le cuivre","Le zinc","Le fer","Le magnésium"]'::jsonb, 0, 'L’or et l’argent non plus : tous les métaux ne sont pas attaqués.', 4),
    ('a815e7a8-130e-5e7b-a6fa-b4fc16342106'::uuid, 'da1a2441-a0f6-5ae8-96a9-da8eb6453c45'::uuid, 'Qu’est-ce que la rouille ?', 'mcq', '["Une transformation chimique du fer en présence d’eau et de dioxygène","Un dépôt de poussière sur le métal","Un changement d’état du fer","Un mélange de fer et de peinture"]'::jsonb, 0, 'C’est une corrosion, donc une réaction chimique lente.', 5),
    ('c30cfbd3-af45-5a22-ae0e-665a8ab3b5ca'::uuid, 'da1a2441-a0f6-5ae8-96a9-da8eb6453c45'::uuid, 'Comment protège-t-on le fer de la corrosion ?', 'mcq', '["En l’isolant par une peinture, une huile ou une galvanisation","En le chauffant régulièrement","En le plongeant dans l’eau salée","En le frottant avec un acide"]'::jsonb, 0, 'On peut aussi employer des alliages inoxydables.', 6),
    ('323005fd-ab59-5938-8f96-7b649578ea84'::uuid, 'da1a2441-a0f6-5ae8-96a9-da8eb6453c45'::uuid, 'Quel danger présente le dihydrogène produit par la réaction ?', 'mcq', '["Il est explosif en présence d’air et d’une flamme","Il est corrosif pour la peau","Il est radioactif","Il éteint les flammes"]'::jsonb, 0, 'Les quantités manipulées doivent rester très faibles.', 7),
    ('4ca896aa-12ee-5f48-b1b8-429c31150594'::uuid, 'da1a2441-a0f6-5ae8-96a9-da8eb6453c45'::uuid, 'La masse de rouille formée est inférieure à la masse de fer disparu.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est supérieure : des atomes d’oxygène se sont ajoutés au fer.', 8),
    ('13bd7509-361b-55ee-922b-d27fabbc5e40'::uuid, '26e6cb06-a1fa-5361-9440-2f0b0719d275'::uuid, 'Quel âge a l’Univers environ ?', 'mcq', '["13,8 milliards d’années","4,6 milliards d’années","1 million d’années","100 milliards d’années"]'::jsonb, 0, 'Le Système solaire, lui, a environ 4,6 milliards d’années.', 1),
    ('35cb0376-1d50-5aca-b6bf-ed19ef83d58a'::uuid, '26e6cb06-a1fa-5361-9440-2f0b0719d275'::uuid, 'Comment s’appelle notre galaxie ?', 'mcq', '["La Voie lactée","Andromède","Le Système solaire","Proxima du Centaure"]'::jsonb, 0, 'Elle contient des centaines de milliards d’étoiles.', 2),
    ('658cfc6f-39bb-531b-abc5-ac7bb7fbd96a'::uuid, '26e6cb06-a1fa-5361-9440-2f0b0719d275'::uuid, 'Combien de planètes compte le Système solaire ?', 'mcq', '["Huit","Neuf","Sept","Douze"]'::jsonb, 0, 'Quatre telluriques et quatre gazeuses.', 3),
    ('834e579f-d82c-5b38-9046-763c96cd2146'::uuid, '26e6cb06-a1fa-5361-9440-2f0b0719d275'::uuid, 'Qu’est-ce qu’une année-lumière ?', 'mcq', '["La distance parcourue par la lumière en un an","La durée d’une révolution terrestre","Le temps mis par la lumière pour atteindre le Soleil","La distance Terre-Soleil"]'::jsonb, 0, 'Environ 9,5 × 10¹² km : c’est une distance, pas une durée.', 4),
    ('fc3f40bc-111a-5d1d-890f-b331fa3ab171'::uuid, '26e6cb06-a1fa-5361-9440-2f0b0719d275'::uuid, 'Quelle est la vitesse de la lumière dans le vide ?', 'mcq', '["Environ 300 000 km/s","Environ 3 000 km/s","Environ 300 km/s","Environ 30 000 km/h"]'::jsonb, 0, 'C’est la vitesse limite de l’Univers.', 5),
    ('ab9e3af0-fe1e-5336-893c-e0dbe270f01d'::uuid, '26e6cb06-a1fa-5361-9440-2f0b0719d275'::uuid, 'Combien de temps la lumière du Soleil met-elle pour nous parvenir ?', 'mcq', '["Environ 8 minutes","Environ 1 seconde","Environ 1 heure","Environ 1 an"]'::jsonb, 0, 'Nous voyons donc le Soleil tel qu’il était il y a 8 minutes.', 6),
    ('4ab71dfb-2d00-5e4a-84c6-8a0092c7e0a9'::uuid, '26e6cb06-a1fa-5361-9440-2f0b0719d275'::uuid, 'Quelle différence y a-t-il entre une étoile et une planète ?', 'mcq', '["L’étoile produit sa lumière, la planète la diffuse","L’étoile est plus proche de nous","La planète est plus chaude","L’étoile tourne autour de la planète"]'::jsonb, 0, 'Le Soleil est une étoile, la Terre une planète.', 7),
    ('1c892375-1388-505a-9019-750e3b46c078'::uuid, '26e6cb06-a1fa-5361-9440-2f0b0719d275'::uuid, 'La Lune produit sa propre lumière.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle diffuse la lumière qu’elle reçoit du Soleil.', 8),
    ('5e569430-051f-5927-90de-df2ed3b36e18'::uuid, '31678240-aedf-5b45-8120-15b60a3f7629'::uuid, 'Que signifie la continuité de la matière dans l’Univers ?', 'mcq', '["La matière est faite partout des mêmes atomes","La matière est répartie uniformément dans l’espace","L’Univers ne contient aucun vide","Toute la matière est en mouvement continu"]'::jsonb, 0, 'Une pierre, un être vivant et une étoile partagent les mêmes éléments.', 1),
    ('ccfeff0c-fc9d-5fa5-b66a-ad431c6c877e'::uuid, '31678240-aedf-5b45-8120-15b60a3f7629'::uuid, 'Quels sont les deux éléments les plus abondants de l’Univers ?', 'mcq', '["L’hydrogène et l’hélium","Le carbone et l’oxygène","Le fer et le silicium","L’azote et l’argon"]'::jsonb, 0, 'Ils se sont formés peu après la naissance de l’Univers.', 2),
    ('35a5d8ab-8d16-5b09-aa5d-6295cbee2288'::uuid, '31678240-aedf-5b45-8120-15b60a3f7629'::uuid, 'Comment connaît-on la composition d’une étoile lointaine ?', 'mcq', '["En analysant le spectre de sa lumière","En y envoyant une sonde","En mesurant sa masse","En comptant ses planètes"]'::jsonb, 0, 'Chaque élément chimique émet ou absorbe des couleurs qui lui sont propres.', 3),
    ('e026af45-6a1b-5070-b0d0-04c2f54a094a'::uuid, '31678240-aedf-5b45-8120-15b60a3f7629'::uuid, 'Où sont fabriqués les éléments chimiques plus lourds que l’hélium ?', 'mcq', '["Au cœur des étoiles","Dans les comètes","Dans l’atmosphère des planètes","Dans le vide interstellaire"]'::jsonb, 0, 'Ils sont dispersés lors de l’explosion des étoiles.', 4),
    ('69a98fe6-34e7-5609-91ee-cba81cc74369'::uuid, '31678240-aedf-5b45-8120-15b60a3f7629'::uuid, 'Quel élément a été identifié dans le Soleil avant de l’être sur Terre ?', 'mcq', '["L’hélium","L’hydrogène","Le fer","Le carbone"]'::jsonb, 0, 'Son nom vient d’ailleurs de Helios, le Soleil.', 5),
    ('148c0ba8-15c6-5942-8f02-3584e6bf43f4'::uuid, '31678240-aedf-5b45-8120-15b60a3f7629'::uuid, 'Quel est l’ordre de grandeur de la taille d’un atome ?', 'mcq', '["10⁻¹⁰ m","10⁻³ m","10⁻⁶ m","10⁻²⁰ m"]'::jsonb, 0, 'Contre environ 10²⁶ m pour l’Univers observable.', 6),
    ('fccb94ef-595a-5830-9c53-ac42341920ba'::uuid, '31678240-aedf-5b45-8120-15b60a3f7629'::uuid, 'Comment la matière s’organise-t-elle dans l’Univers ?', 'mcq', '["En niveaux emboîtés, de l’atome aux galaxies","De façon totalement désordonnée","Uniquement en molécules","En couches concentriques autour de la Terre"]'::jsonb, 0, 'Atomes, molécules, cellules, organismes, planètes, étoiles, galaxies.', 7),
    ('98672ccf-8114-599d-bc21-5b196fdf4299'::uuid, '31678240-aedf-5b45-8120-15b60a3f7629'::uuid, 'Les lois de la physique diffèrent d’une galaxie à l’autre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est leur universalité, vérifiée par l’observation, qui rend l’astrophysique possible.', 8),
    ('f45bbd31-7a4f-5e36-97f3-a3bb09ed2325'::uuid, '074d7676-aa3f-53c8-a9e3-5f22eaa56020'::uuid, 'Quelles particules composent le noyau d’un atome ?', 'mcq', '["Les protons et les neutrons","Les protons et les électrons","Les électrons et les neutrons","Uniquement les protons"]'::jsonb, 0, 'On les appelle collectivement les nucléons.', 1),
    ('edde2791-0da5-5932-9d73-375e0c24ddaf'::uuid, '074d7676-aa3f-53c8-a9e3-5f22eaa56020'::uuid, 'Quelle est la charge d’un neutron ?', 'mcq', '["Nulle","Positive","Négative","Variable"]'::jsonb, 0, 'Le proton est positif, l’électron négatif.', 2),
    ('3a8477b1-3515-5b72-81f7-b74ee38fc208'::uuid, '074d7676-aa3f-53c8-a9e3-5f22eaa56020'::uuid, 'Pourquoi un atome est-il électriquement neutre ?', 'mcq', '["Parce qu’il a autant de protons que d’électrons","Parce qu’il n’a pas de charge du tout","Parce que les neutrons annulent les protons","Parce que les électrons sont immobiles"]'::jsonb, 0, 'Gagner ou perdre des électrons en fait un ion.', 3),
    ('8a27fef9-d5fd-583c-afec-3e2367ffbf14'::uuid, '074d7676-aa3f-53c8-a9e3-5f22eaa56020'::uuid, 'Où se concentre presque toute la masse d’un atome ?', 'mcq', '["Dans le noyau","Dans les électrons","Dans le vide qui l’entoure","Elle est répartie uniformément"]'::jsonb, 0, 'Un électron est environ 2 000 fois plus léger qu’un nucléon.', 4),
    ('ef256d4f-0d11-510e-877d-9ecbeafcf47c'::uuid, '074d7676-aa3f-53c8-a9e3-5f22eaa56020'::uuid, 'Combien de fois le noyau est-il plus petit que l’atome ?', 'mcq', '["Environ 100 000 fois","Environ 10 fois","Environ 1 000 fois","Ils ont la même taille"]'::jsonb, 0, 'L’atome est donc essentiellement constitué de vide.', 5),
    ('513d2467-dc95-5d80-a0e0-13df9f18b3ea'::uuid, '074d7676-aa3f-53c8-a9e3-5f22eaa56020'::uuid, 'Qu’est-ce qui identifie un élément chimique ?', 'mcq', '["Son nombre de protons","Son nombre de neutrons","Son nombre d’électrons","Sa masse totale"]'::jsonb, 0, 'Le carbone a 6 protons, l’oxygène 8.', 6),
    ('7c224b98-87b1-5600-b7a1-22c597935101'::uuid, '074d7676-aa3f-53c8-a9e3-5f22eaa56020'::uuid, 'Que représente le 2 dans la formule H₂O ?', 'mcq', '["Le nombre d’atomes d’hydrogène dans la molécule","Le nombre de molécules d’eau","La charge de la molécule","Le nombre de liaisons"]'::jsonb, 0, 'L’indice compte les atomes du symbole qui le précède.', 7),
    ('019f4580-2a3c-51ed-9050-0bd6672856ee'::uuid, '074d7676-aa3f-53c8-a9e3-5f22eaa56020'::uuid, 'Un atome peut gagner ou perdre des protons pour devenir un ion.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Seuls les électrons sont échangés : changer le nombre de protons changerait d’élément.', 8),
    ('5fcfae3a-8852-57ad-a4bf-762562f57467'::uuid, '26a174af-44f0-5be4-b697-2737d306e481'::uuid, 'De quoi dépend la description d’un mouvement ?', 'mcq', '["Du référentiel choisi","De la masse de l’objet","De la couleur de l’objet","De rien : elle est absolue"]'::jsonb, 0, 'Un passager de train est immobile dans le train et en mouvement par rapport au quai.', 1),
    ('5c83d1b5-95d5-5c9e-be16-6a27f1622af8'::uuid, '26a174af-44f0-5be4-b697-2737d306e481'::uuid, 'Qu’appelle-t-on trajectoire ?', 'mcq', '["La ligne décrite par l’objet au cours du temps","La vitesse de l’objet","La durée du trajet","La force appliquée"]'::jsonb, 0, 'Elle peut être rectiligne, circulaire ou curviligne.', 2),
    ('2c37588d-60a6-59de-92ed-6e5db8a72128'::uuid, '26a174af-44f0-5be4-b697-2737d306e481'::uuid, 'Quelle est la formule de la vitesse ?', 'mcq', '["v = d ÷ t","v = d × t","v = t ÷ d","v = d + t"]'::jsonb, 0, 'Distance parcourue divisée par la durée.', 3),
    ('4c7c212f-7c1f-5c4c-a02d-a8d8e5477944'::uuid, '26a174af-44f0-5be4-b697-2737d306e481'::uuid, 'Comment convertit-on une vitesse de km/h en m/s ?', 'mcq', '["On divise par 3,6","On multiplie par 3,6","On divise par 1 000","On multiplie par 60"]'::jsonb, 0, '36 km/h correspondent à 10 m/s.', 4),
    ('acae5a95-b72e-5ff7-86c6-061d8ab70b2c'::uuid, '26a174af-44f0-5be4-b697-2737d306e481'::uuid, 'Qu’est-ce qu’un mouvement uniforme ?', 'mcq', '["Un mouvement dont la vitesse ne change pas","Un mouvement en ligne droite","Un mouvement circulaire","Un mouvement sans force"]'::jsonb, 0, 'Uniforme parle de la vitesse, rectiligne parle de la trajectoire.', 5),
    ('915ff294-acc8-535e-84bc-00a4363c46db'::uuid, '26a174af-44f0-5be4-b697-2737d306e481'::uuid, 'Quelle différence y a-t-il entre vitesse moyenne et vitesse instantanée ?', 'mcq', '["La moyenne porte sur tout le trajet, l’instantanée sur un instant précis","La moyenne est toujours plus grande","L’instantanée ne se mesure pas","Ce sont deux mots pour la même grandeur"]'::jsonb, 0, 'Le compteur d’une voiture affiche la vitesse instantanée.', 6),
    ('498f5255-c04d-53ca-a791-e9bf5fdf214c'::uuid, '26a174af-44f0-5be4-b697-2737d306e481'::uuid, 'Que montre une chronophotographie où les positions s’espacent de plus en plus ?', 'mcq', '["Un mouvement accéléré","Un mouvement uniforme","Un mouvement ralenti","Un objet immobile"]'::jsonb, 0, 'Des intervalles de temps égaux, des distances croissantes.', 7),
    ('55a1a783-a6bb-588c-b958-f9c6e5dc6366'::uuid, '26a174af-44f0-5be4-b697-2737d306e481'::uuid, 'Un objet peut être à la fois immobile et en mouvement.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Selon le référentiel choisi : c’est la relativité du mouvement.', 8),
    ('644ba9fc-6f33-5a3c-b0bd-fc8d6181948b'::uuid, '5aeb3ec5-6231-57b7-83a5-3843b90b890b'::uuid, 'Comment appelle-t-on l’action qu’un objet exerce sur un autre ?', 'mcq', '["Une force","Une énergie","Une puissance","Une vitesse"]'::jsonb, 0, 'Elle modélise une interaction entre deux objets.', 1),
    ('f2023560-5152-5deb-8b34-dfd55cc0546a'::uuid, '5aeb3ec5-6231-57b7-83a5-3843b90b890b'::uuid, 'Quelle interaction s’exerce sans contact ?', 'mcq', '["L’interaction gravitationnelle","Le frottement","La poussée d’une main","Le soutien d’une table"]'::jsonb, 0, 'L’interaction magnétique et l’électrostatique aussi.', 2),
    ('c41dbc54-7f70-5cb3-a469-b559cfd35ab2'::uuid, '5aeb3ec5-6231-57b7-83a5-3843b90b890b'::uuid, 'Dans quelle unité mesure-t-on une force ?', 'mcq', '["Le newton (N)","Le joule (J)","Le watt (W)","Le kilogramme (kg)"]'::jsonb, 0, 'On la mesure avec un dynamomètre.', 3),
    ('015be0b3-952a-59b8-b0a5-72d3af00ceab'::uuid, '5aeb3ec5-6231-57b7-83a5-3843b90b890b'::uuid, 'Combien d’informations une flèche représentant une force porte-t-elle ?', 'mcq', '["Quatre : point d’application, direction, sens et valeur","Deux : direction et valeur","Une seule : la valeur","Trois : direction, sens et masse"]'::jsonb, 0, 'La longueur de la flèche traduit la valeur.', 4),
    ('b76a9422-d58e-54d7-8420-cf53dd8ab0d9'::uuid, '5aeb3ec5-6231-57b7-83a5-3843b90b890b'::uuid, 'Quel effet une force ne peut-elle PAS produire ?', 'mcq', '["Changer la nature chimique de l’objet","Mettre l’objet en mouvement","Modifier sa trajectoire","Le déformer"]'::jsonb, 0, 'Une force agit sur le mouvement ou la forme, pas sur la composition.', 5),
    ('be206c07-038a-56e1-b952-1dd3519128ae'::uuid, '5aeb3ec5-6231-57b7-83a5-3843b90b890b'::uuid, 'Que dit le principe des actions réciproques ?', 'mcq', '["Si A exerce une force sur B, B exerce sur A une force opposée de même valeur","La force la plus grande l’emporte toujours","Les forces s’additionnent toujours","Une force à distance est plus faible qu’une force de contact"]'::jsonb, 0, 'Le nageur pousse l’eau, l’eau pousse le nageur.', 6),
    ('ff826d9a-80bb-523d-a882-0e254bbe2ab0'::uuid, '5aeb3ec5-6231-57b7-83a5-3843b90b890b'::uuid, 'Que se passe-t-il quand les forces exercées sur un objet se compensent ?', 'mcq', '["Il reste immobile ou garde un mouvement rectiligne uniforme","Il s’arrête immédiatement","Il accélère","Il se déforme"]'::jsonb, 0, 'Il faut une force résultante non nulle pour changer le mouvement.', 7),
    ('846a9704-d946-5a78-986c-6eccdcf16a43'::uuid, '5aeb3ec5-6231-57b7-83a5-3843b90b890b'::uuid, 'Un objet en mouvement a besoin d’une force pour continuer d’avancer.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il en a besoin pour changer de mouvement, pas pour le maintenir.', 8),
    ('358a0a3a-1b39-551b-accd-83ebf81c619a'::uuid, '226fd74e-8407-5edc-8e42-5fa611ed97d5'::uuid, 'De quoi dépend la force d’attraction gravitationnelle ?', 'mcq', '["Des masses des deux corps et de la distance qui les sépare","De leur couleur et de leur volume","De leur température","De leur vitesse uniquement"]'::jsonb, 0, 'Elle augmente avec les masses et diminue avec la distance.', 1),
    ('98d8bdd9-6ee0-517f-b97a-8e06130334d0'::uuid, '226fd74e-8407-5edc-8e42-5fa611ed97d5'::uuid, 'Quelle est la formule du poids ?', 'mcq', '["P = m × g","P = m ÷ g","P = g ÷ m","P = m + g"]'::jsonb, 0, 'Le poids en newtons, la masse en kilogrammes.', 2),
    ('a0d67575-bf72-591c-8a13-b89a05185c35'::uuid, '226fd74e-8407-5edc-8e42-5fa611ed97d5'::uuid, 'Quelle est l’unité du poids ?', 'mcq', '["Le newton (N)","Le kilogramme (kg)","Le joule (J)","Le pascal (Pa)"]'::jsonb, 0, 'Le kilogramme est l’unité de la masse.', 3),
    ('b6f47868-4585-5986-beff-937142d175a1'::uuid, '226fd74e-8407-5edc-8e42-5fa611ed97d5'::uuid, 'Que vaut environ l’intensité de la pesanteur sur Terre ?', 'mcq', '["9,8 N/kg","1,6 N/kg","98 N/kg","0,98 N/kg"]'::jsonb, 0, 'Sur la Lune, elle vaut environ 1,6 N/kg.', 4),
    ('9862d5c7-47d1-547e-a70e-07561e4ba0b6'::uuid, '226fd74e-8407-5edc-8e42-5fa611ed97d5'::uuid, 'Que devient la masse d’un objet transporté sur la Lune ?', 'mcq', '["Elle ne change pas","Elle est divisée par 6","Elle est multipliée par 6","Elle devient nulle"]'::jsonb, 0, 'C’est le poids, et lui seul, qui est divisé par 6.', 5),
    ('8b376801-b5c7-55d2-be3a-2c98f1147c62'::uuid, '226fd74e-8407-5edc-8e42-5fa611ed97d5'::uuid, 'Quel instrument mesure un poids ?', 'mcq', '["Le dynamomètre","La balance","Le baromètre","Le voltmètre"]'::jsonb, 0, 'La balance mesure une masse, en kilogrammes.', 6),
    ('7f7b41d9-5af7-5711-af13-7f9b9ecda029'::uuid, '226fd74e-8407-5edc-8e42-5fa611ed97d5'::uuid, 'Quelle est la direction du poids ?', 'mcq', '["Verticale, vers le bas","Horizontale","Vers le haut","Elle change selon le mouvement"]'::jsonb, 0, 'Il est dirigé vers le centre de l’astre.', 7),
    ('fc17e99c-fd3e-522a-b366-469a4f66b937'::uuid, '226fd74e-8407-5edc-8e42-5fa611ed97d5'::uuid, 'Sans la gravitation, les planètes continueraient de tourner autour du Soleil.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles partiraient en ligne droite : c’est la gravitation qui courbe leur trajectoire.', 8),
    ('70fa4469-b143-5df9-8d86-1db4592134fb'::uuid, '64265d5d-305c-514d-9679-87c2945c375d'::uuid, 'Quelle est l’unité légale de l’énergie ?', 'mcq', '["Le joule (J)","Le watt (W)","Le newton (N)","Le volt (V)"]'::jsonb, 0, 'Le watt est l’unité de la puissance, pas de l’énergie.', 1),
    ('107edd8f-2de2-5826-ade1-9f46f76d7ddd'::uuid, '64265d5d-305c-514d-9679-87c2945c375d'::uuid, 'À quelle grandeur l’énergie cinétique est-elle liée ?', 'mcq', '["Au mouvement de l’objet","À sa hauteur","À sa température","À sa composition chimique"]'::jsonb, 0, 'Ec = ½ × m × v².', 2),
    ('52c1e329-c813-50e3-bb03-e308ff4186e8'::uuid, '64265d5d-305c-514d-9679-87c2945c375d'::uuid, 'Quelle forme d’énergie un aliment contient-il ?', 'mcq', '["De l’énergie chimique","De l’énergie cinétique","De l’énergie nucléaire","De l’énergie électrique"]'::jsonb, 0, 'Elle est stockée dans les liaisons entre atomes.', 3),
    ('028785e0-2748-53db-ae8b-f411f8e31a16'::uuid, '64265d5d-305c-514d-9679-87c2945c375d'::uuid, 'À combien de joules correspond 1 kWh ?', 'mcq', '["3,6 × 10⁶ J","1 000 J","3 600 J","10⁶ J"]'::jsonb, 0, 'Un appareil de 1 000 W pendant une heure consomme 1 kWh.', 4),
    ('762fa142-cc8a-57b6-81c7-ad4c677068e3'::uuid, '64265d5d-305c-514d-9679-87c2945c375d'::uuid, 'Quelle source d’énergie est renouvelable ?', 'mcq', '["L’énergie éolienne","Le charbon","Le pétrole","L’uranium"]'::jsonb, 0, 'Elle se reconstitue à l’échelle d’une vie humaine.', 5),
    ('39f8d804-9aaa-59ab-8fef-707c6f786d31'::uuid, '64265d5d-305c-514d-9679-87c2945c375d'::uuid, 'De quoi dépend l’énergie de position d’un objet ?', 'mcq', '["De sa masse et de sa hauteur","De sa vitesse","De sa température","De sa couleur"]'::jsonb, 0, 'Epp = m × g × h.', 6),
    ('33ae2771-a973-54eb-8b9e-d6b6cce341d4'::uuid, '64265d5d-305c-514d-9679-87c2945c375d'::uuid, 'Quelle est la différence entre une source et une forme d’énergie ?', 'mcq', '["La source est ce d’où l’on tire l’énergie, la forme est la manière dont elle se présente","Ce sont deux mots pour la même chose","La source est toujours renouvelable","La forme se mesure en watts"]'::jsonb, 0, 'Le pétrole est une source, l’énergie chimique une forme.', 7),
    ('a271911d-7d73-5997-9736-d1dbb08177b6'::uuid, '64265d5d-305c-514d-9679-87c2945c375d'::uuid, 'Le watt est une unité d’énergie.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’unité de la puissance : une énergie par unité de temps.', 8),
    ('b1f2e111-7181-5a77-94ce-35fecd23d17d'::uuid, '1d2ee836-c30e-5104-b473-c7769734f204'::uuid, 'Quelle est la différence entre transfert et conversion d’énergie ?', 'mcq', '["Le transfert déplace l’énergie, la conversion change sa forme","Le transfert change la forme, la conversion déplace l’énergie","Ce sont deux mots pour la même chose","Le transfert ne concerne que l’électricité"]'::jsonb, 0, 'Un radiateur transfère, une lampe convertit.', 1),
    ('bd117286-5b0c-5705-8742-3d3f9ba42cc4'::uuid, '1d2ee836-c30e-5104-b473-c7769734f204'::uuid, 'Quel mode de transfert thermique se fait sans support matériel ?', 'mcq', '["Le rayonnement","La conduction","La convection","La conversion"]'::jsonb, 0, 'C’est ainsi que la chaleur du Soleil traverse le vide.', 2),
    ('40c4808f-d6f5-57e2-960c-316eb8761fc2'::uuid, '1d2ee836-c30e-5104-b473-c7769734f204'::uuid, 'Quel mode de transfert explique qu’une cuillère chauffe dans une casserole ?', 'mcq', '["La conduction","La convection","Le rayonnement","La combustion"]'::jsonb, 0, 'La chaleur se propage de proche en proche dans le métal.', 3),
    ('28044b2f-6d98-5ed1-8718-38c1ea9611aa'::uuid, '1d2ee836-c30e-5104-b473-c7769734f204'::uuid, 'Quelle conversion réalise un panneau photovoltaïque ?', 'mcq', '["Lumineuse → électrique","Électrique → lumineuse","Chimique → électrique","Cinétique → électrique"]'::jsonb, 0, 'L’alternateur, lui, convertit du cinétique en électrique.', 4),
    ('a968576c-a9a9-5661-bf1a-e649ed17fb2c'::uuid, '1d2ee836-c30e-5104-b473-c7769734f204'::uuid, 'Quelle conversion réalise une pile ?', 'mcq', '["Chimique → électrique","Électrique → chimique","Thermique → électrique","Lumineuse → chimique"]'::jsonb, 0, 'L’énergie est stockée dans les liaisons entre atomes.', 5),
    ('add96f47-0d96-5e70-ae03-4147adefb227'::uuid, '1d2ee836-c30e-5104-b473-c7769734f204'::uuid, 'Comment calcule-t-on un rendement ?', 'mcq', '["Énergie utile ÷ énergie reçue","Énergie reçue ÷ énergie utile","Énergie utile × énergie perdue","Énergie perdue ÷ énergie utile"]'::jsonb, 0, 'On l’exprime le plus souvent en pourcentage.', 6),
    ('1b21734c-ad21-50f9-91e7-830ef7fd70aa'::uuid, '1d2ee836-c30e-5104-b473-c7769734f204'::uuid, 'Que représente la flèche latérale d’une chaîne énergétique ?', 'mcq', '["Les pertes, presque toujours thermiques","L’énergie utile","La source d’énergie","La puissance de l’appareil"]'::jsonb, 0, 'Aucun convertisseur réel n’est parfait.', 7),
    ('03ff3f4c-329c-57c0-a5d1-402486a3225c'::uuid, '1d2ee836-c30e-5104-b473-c7769734f204'::uuid, 'La chaleur peut passer spontanément d’un corps froid à un corps chaud.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le transfert thermique va toujours du plus chaud vers le plus froid.', 8),
    ('cb153013-ac95-54d7-b94d-f868da784c53'::uuid, '8a175c42-9ca5-5652-912c-ba838286c6b7'::uuid, 'Quelle est la formule de l’énergie cinétique ?', 'mcq', '["Ec = ½ × m × v²","Ec = m × v","Ec = m × g × h","Ec = ½ × m × v"]'::jsonb, 0, 'La vitesse intervient au carré.', 1),
    ('a90b1c02-aca4-51a6-af43-7dd215184878'::uuid, '8a175c42-9ca5-5652-912c-ba838286c6b7'::uuid, 'Dans quelle unité doit être exprimée la vitesse dans cette formule ?', 'mcq', '["En mètres par seconde (m/s)","En kilomètres par heure (km/h)","En mètres par heure","En newtons"]'::jsonb, 0, 'On divise les km/h par 3,6 avant tout calcul.', 2),
    ('0467b0ba-e807-5581-838c-6e3f70f2ca8a'::uuid, '8a175c42-9ca5-5652-912c-ba838286c6b7'::uuid, 'Par combien l’énergie cinétique est-elle multipliée si la vitesse double ?', 'mcq', '["4","2","8","16"]'::jsonb, 0, 'La vitesse est élevée au carré : 2² = 4.', 3),
    ('dbf1b732-1ca3-5aa4-a8c9-1abd34d53b74'::uuid, '8a175c42-9ca5-5652-912c-ba838286c6b7'::uuid, 'Par combien l’énergie cinétique est-elle multipliée si la masse double ?', 'mcq', '["2","4","8","Elle ne change pas"]'::jsonb, 0, 'La masse, elle, intervient au premier degré.', 4),
    ('2e34ff8c-d707-5cbf-ac0f-d6ea1ed94322'::uuid, '8a175c42-9ca5-5652-912c-ba838286c6b7'::uuid, 'Quelle est l’énergie cinétique d’une voiture de 1 000 kg roulant à 20 m/s ?', 'mcq', '["200 000 J","20 000 J","400 000 J","10 000 J"]'::jsonb, 0, 'Ec = 0,5 × 1 000 × 400.', 5),
    ('e0dd755b-7481-566e-a066-37fc5e7ec2f6'::uuid, '8a175c42-9ca5-5652-912c-ba838286c6b7'::uuid, 'De quoi se compose la distance d’arrêt ?', 'mcq', '["De la distance de réaction et de la distance de freinage","De la distance de freinage seulement","De la distance parcourue avant le virage","De la longueur du véhicule"]'::jsonb, 0, 'Le temps de réaction est d’environ une seconde.', 6),
    ('392b2cfd-8677-5812-849d-3c78842031a3'::uuid, '8a175c42-9ca5-5652-912c-ba838286c6b7'::uuid, 'Que devient l’énergie cinétique d’un véhicule qui freine ?', 'mcq', '["Elle est convertie en énergie thermique par les frottements","Elle disparaît","Elle devient de l’énergie chimique","Elle est stockée dans le moteur"]'::jsonb, 0, 'Les disques de frein chauffent : l’énergie a changé de forme.', 7),
    ('8b4fae80-743e-5f00-8360-4049adcbc5ba'::uuid, '8a175c42-9ca5-5652-912c-ba838286c6b7'::uuid, 'Doubler sa vitesse double la violence d’un choc.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est multipliée par quatre : c’est tout le sens du carré dans la formule.', 8),
    ('8375cd4b-9371-5266-a196-7f409cad5619'::uuid, '2f109b8f-81b9-5c70-ac50-537a7dfb85a3'::uuid, 'Que dit le principe de conservation de l’énergie ?', 'mcq', '["L’énergie ne se crée pas et ne se détruit pas, elle se transforme","L’énergie diminue à chaque conversion","L’énergie augmente avec la température","L’énergie disparaît lors des frottements"]'::jsonb, 0, 'La somme des formes d’énergie reste constante dans un système isolé.', 1),
    ('bdf46ef3-18e9-5b4f-8113-67d95948cb57'::uuid, '2f109b8f-81b9-5c70-ac50-537a7dfb85a3'::uuid, 'Sous quelle forme les pertes d’énergie apparaissent-elles le plus souvent ?', 'mcq', '["Sous forme thermique","Sous forme chimique","Sous forme nucléaire","Sous forme lumineuse"]'::jsonb, 0, 'Frottements et effet Joule dissipent de la chaleur.', 2),
    ('dc2c88b9-3410-5c3d-9158-a52ca61adc5e'::uuid, '2f109b8f-81b9-5c70-ac50-537a7dfb85a3'::uuid, 'Que signifie « énergie dégradée » ?', 'mcq', '["Une énergie trop diluée dans l’environnement pour être réutilisée","Une énergie qui a disparu","Une énergie de mauvaise qualité chimique","Une énergie négative"]'::jsonb, 0, 'Elle figure toujours au bilan, mais elle est inexploitable.', 3),
    ('79ff0093-3402-51d6-bbe8-3b814c94d812'::uuid, '2f109b8f-81b9-5c70-ac50-537a7dfb85a3'::uuid, 'Quel est l’ordre de grandeur du rendement d’un moteur thermique de voiture ?', 'mcq', '["Environ 30 %","Environ 90 %","Environ 5 %","Environ 70 %"]'::jsonb, 0, 'Les deux tiers de l’énergie du carburant partent en chaleur.', 4),
    ('91c8f940-fc3b-52d1-90e0-2a94c832f527'::uuid, '2f109b8f-81b9-5c70-ac50-537a7dfb85a3'::uuid, 'Quel convertisseur a le meilleur rendement ?', 'mcq', '["Le moteur électrique","Le moteur thermique","La lampe à incandescence","La chaudière à charbon"]'::jsonb, 0, 'Il peut dépasser 90 %.', 5),
    ('75a97b64-5d9c-5d99-ac91-c5e139caa106'::uuid, '2f109b8f-81b9-5c70-ac50-537a7dfb85a3'::uuid, 'Que se passe-t-il pour une bille qui tombe, si l’on néglige les frottements ?', 'mcq', '["Son énergie de position se convertit en énergie cinétique","Son énergie totale augmente","Son énergie cinétique se convertit en énergie chimique","Elle perd toute son énergie"]'::jsonb, 0, 'La somme des deux formes reste constante.', 6),
    ('200549ca-d91b-5554-a68e-40e723576d89'::uuid, '2f109b8f-81b9-5c70-ac50-537a7dfb85a3'::uuid, 'Quelle est la manière la plus efficace d’économiser l’énergie d’un logement ?', 'mcq', '["L’isoler pour limiter les transferts thermiques","Augmenter la puissance du chauffage","Ouvrir les fenêtres régulièrement","Remplacer les meubles"]'::jsonb, 0, 'Moins de transferts vers l’extérieur, moins d’énergie à fournir.', 7),
    ('39141d2c-5cdd-5fbf-90f8-a6bde4b9947f'::uuid, '2f109b8f-81b9-5c70-ac50-537a7dfb85a3'::uuid, 'Un rendement de 100 % est possible dans un appareil réel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une part d’énergie est toujours dissipée sous forme thermique.', 8),
    ('b4f1564f-c7e7-5e78-811d-81043802c7f2'::uuid, '1f6fa480-57ea-5c2f-b14e-edc709315925'::uuid, 'Qu’est-ce que le courant électrique dans un métal ?', 'mcq', '["Un déplacement ordonné d’électrons libres","Un déplacement d’ions","Un déplacement d’atomes entiers","Un rayonnement lumineux"]'::jsonb, 0, 'Dans une solution, ce sont les ions qui se déplacent.', 1),
    ('a41b9936-611d-5b80-8526-7fbe4698ba40'::uuid, '1f6fa480-57ea-5c2f-b14e-edc709315925'::uuid, 'À quelle condition le courant circule-t-il ?', 'mcq', '["Le circuit doit être fermé","Le circuit doit être ouvert","Il faut au moins deux générateurs","Il faut que le circuit soit chaud"]'::jsonb, 0, 'Un interrupteur ouvert interrompt la boucle.', 2),
    ('896387ba-e0f1-5e4b-b467-d9dbcbabaf23'::uuid, '1f6fa480-57ea-5c2f-b14e-edc709315925'::uuid, 'Quel est le sens conventionnel du courant à l’extérieur du générateur ?', 'mcq', '["De la borne + vers la borne −","De la borne − vers la borne +","Il change constamment","Il dépend du récepteur"]'::jsonb, 0, 'Les électrons, eux, circulent en sens inverse.', 3),
    ('da311724-1e18-52ec-a0de-7ef8055a54fb'::uuid, '1f6fa480-57ea-5c2f-b14e-edc709315925'::uuid, 'Qu’est-ce qu’un court-circuit ?', 'mcq', '["Une liaison directe entre les deux bornes du générateur","Un circuit trop long","Un circuit sans récepteur ni générateur","Un circuit ouvert"]'::jsonb, 0, 'L’intensité devient très grande : les fils chauffent, c’est un danger d’incendie.', 4),
    ('abcd45c8-ae02-578e-9915-29c8009076f7'::uuid, '1f6fa480-57ea-5c2f-b14e-edc709315925'::uuid, 'Lequel de ces matériaux est un isolant ?', 'mcq', '["Le plastique","Le cuivre","Le graphite","L’eau salée"]'::jsonb, 0, 'Les métaux, le graphite et les solutions ioniques conduisent.', 5),
    ('35dfa156-d871-5284-baef-d3513ac147a3'::uuid, '1f6fa480-57ea-5c2f-b14e-edc709315925'::uuid, 'Quel élément du circuit fournit l’énergie électrique ?', 'mcq', '["Le générateur","Le récepteur","L’interrupteur","Le fil de connexion"]'::jsonb, 0, 'La lampe et le moteur, eux, la consomment.', 6),
    ('d01eb5c5-7e3d-5858-8633-90000459d7b7'::uuid, '1f6fa480-57ea-5c2f-b14e-edc709315925'::uuid, 'Pourquoi le corps humain est-il dangereux face à l’électricité ?', 'mcq', '["Parce qu’il est conducteur, surtout s’il est humide","Parce qu’il est isolant","Parce qu’il produit du courant","Parce qu’il stocke les charges"]'::jsonb, 0, 'C’est la raison de toutes les règles de sécurité électrique.', 7),
    ('018ed348-157a-5781-8dda-fed44c904ac4'::uuid, '1f6fa480-57ea-5c2f-b14e-edc709315925'::uuid, 'Les électrons circulent dans le sens conventionnel du courant.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils circulent en sens inverse : la convention date d’avant leur découverte.', 8),
    ('a4c9c792-a808-5b57-aad9-9faae6b82fc1'::uuid, 'f9d5c161-34f0-5249-9ebb-d8f03e5b15ef'::uuid, 'Dans un montage en série, que peut-on dire de l’intensité ?', 'mcq', '["Elle est la même en tout point du circuit","Elle s’additionne à chaque dipôle","Elle diminue à chaque dipôle","Elle est nulle après le premier dipôle"]'::jsonb, 0, 'Le courant n’a qu’un seul chemin possible.', 1),
    ('f6781067-ff43-5244-84af-b98e9d86ea2a'::uuid, 'f9d5c161-34f0-5249-9ebb-d8f03e5b15ef'::uuid, 'Dans un montage en dérivation, que peut-on dire de la tension aux bornes de chaque branche ?', 'mcq', '["Elle est la même que celle du générateur","Elle se partage entre les branches","Elle s’additionne","Elle est nulle"]'::jsonb, 0, 'C’est pourquoi chaque appareil domestique reçoit 230 V.', 2),
    ('607c2b93-ead3-5cd6-9852-44c050f8d10b'::uuid, 'f9d5c161-34f0-5249-9ebb-d8f03e5b15ef'::uuid, 'Que se passe-t-il si une lampe grille dans un montage en série ?', 'mcq', '["Tout le circuit s’éteint","Les autres lampes brillent davantage","Rien ne change","Le générateur se coupe"]'::jsonb, 0, 'La boucle unique est ouverte.', 3),
    ('5ea595f9-f8f0-5dfd-a1d4-b7869acde66b'::uuid, 'f9d5c161-34f0-5249-9ebb-d8f03e5b15ef'::uuid, 'Que se passe-t-il si une lampe grille dans un montage en dérivation ?', 'mcq', '["Les autres continuent de fonctionner","Tout s’éteint","Le générateur se met en court-circuit","La tension double"]'::jsonb, 0, 'Chaque branche est indépendante.', 4),
    ('a3f2af4f-6572-5eda-a87c-fc8e5d6ee234'::uuid, 'f9d5c161-34f0-5249-9ebb-d8f03e5b15ef'::uuid, 'Que dit la loi des nœuds ?', 'mcq', '["L’intensité qui arrive à un nœud est égale à la somme des intensités qui en repartent","Les tensions s’additionnent aux nœuds","L’intensité est nulle aux nœuds","La résistance se partage aux nœuds"]'::jsonb, 0, 'Elle traduit la conservation de la charge électrique.', 5),
    ('fb4a739d-5370-52a7-bde5-a9c7894ed84d'::uuid, 'f9d5c161-34f0-5249-9ebb-d8f03e5b15ef'::uuid, 'Comment se branche un ampèremètre ?', 'mcq', '["En série, dans la branche à mesurer","En dérivation, aux bornes du dipôle","Directement aux bornes du générateur","Peu importe"]'::jsonb, 0, 'Branché en dérivation, il provoquerait un court-circuit.', 6),
    ('750cd2db-8b5e-53e5-b47f-ccaddb6192b4'::uuid, 'f9d5c161-34f0-5249-9ebb-d8f03e5b15ef'::uuid, 'Comment se branche un voltmètre ?', 'mcq', '["En dérivation, aux bornes du dipôle","En série avec le dipôle","À la place du générateur","En série avec l’ampèremètre"]'::jsonb, 0, 'Il mesure une différence de potentiel entre deux points.', 7),
    ('d0d388fa-c475-59ce-a515-2c99d3c9e87a'::uuid, 'f9d5c161-34f0-5249-9ebb-d8f03e5b15ef'::uuid, 'Les installations électriques domestiques sont montées en série.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles sont en dérivation : chaque appareil reçoit 230 V et fonctionne indépendamment.', 8),
    ('a3895ebd-8c2d-5bab-9147-32e37159bff7'::uuid, 'e600d2f2-d2d5-533d-a595-cb545436aa10'::uuid, 'Dans quelle unité se mesure la tension électrique ?', 'mcq', '["Le volt (V)","L’ampère (A)","L’ohm (Ω)","Le watt (W)"]'::jsonb, 0, 'L’ampère est l’unité de l’intensité.', 1),
    ('973fbb14-a561-502e-911c-bd9245b58280'::uuid, 'e600d2f2-d2d5-533d-a595-cb545436aa10'::uuid, 'Comment se branche un voltmètre ?', 'mcq', '["En dérivation, aux bornes du dipôle","En série avec le dipôle","À la place du générateur","Entre deux nœuds vides"]'::jsonb, 0, 'Il mesure une différence entre deux points.', 2),
    ('d50a1630-f219-5758-b86c-e46b4fee10e2'::uuid, 'e600d2f2-d2d5-533d-a595-cb545436aa10'::uuid, 'Quelle est la tension du secteur domestique en France ?', 'mcq', '["230 V","12 V","4,5 V","1 000 V"]'::jsonb, 0, 'Une tension mortelle : au-delà de 25 V, le danger est réel.', 3),
    ('f9d9d9d6-654d-5493-951c-f1ff4ab49364'::uuid, 'e600d2f2-d2d5-533d-a595-cb545436aa10'::uuid, 'Que deviennent les tensions dans un montage en série ?', 'mcq', '["Elles s’additionnent","Elles sont égales partout","Elles se divisent par le nombre de dipôles","Elles s’annulent"]'::jsonb, 0, 'En dérivation, en revanche, elles sont égales.', 4),
    ('9778ea22-1447-544d-9449-b868a097df6a'::uuid, 'e600d2f2-d2d5-533d-a595-cb545436aa10'::uuid, 'Quelle est la tension aux bornes d’un interrupteur fermé ?', 'mcq', '["Environ 0 V","La tension du générateur","La moitié de la tension du générateur","Elle est négative"]'::jsonb, 0, 'Ouvert, il porterait au contraire toute la tension du générateur.', 5),
    ('4b19050f-52a9-5dfe-a27d-3b6794193ccc'::uuid, 'e600d2f2-d2d5-533d-a595-cb545436aa10'::uuid, 'Que se passe-t-il si l’on inverse les bornes d’un voltmètre ?', 'mcq', '["Il affiche une valeur négative","Il grille immédiatement","Il provoque un court-circuit","Il n’affiche plus rien"]'::jsonb, 0, 'Seul le signe change ; le circuit ne risque rien.', 6),
    ('be6a969c-f758-5de5-9f49-20c30ff6df43'::uuid, 'e600d2f2-d2d5-533d-a595-cb545436aa10'::uuid, 'Quelle est la fréquence de la tension du secteur en France ?', 'mcq', '["50 Hz","60 Hz","100 Hz","230 Hz"]'::jsonb, 0, 'La tension alternative change de signe 50 fois par seconde.', 7),
    ('a3976947-7d24-508e-8194-1c94feee403c'::uuid, 'e600d2f2-d2d5-533d-a595-cb545436aa10'::uuid, 'Une tension ne peut exister que si un courant circule.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une pile isolée a bien une tension à ses bornes sans qu’aucun courant ne passe.', 8),
    ('16a7755f-1dab-5b87-879d-f7ac51d3df41'::uuid, 'bd683e3d-650d-5e95-a5f2-8a9e51bd159c'::uuid, 'Dans quelle unité se mesure l’intensité du courant ?', 'mcq', '["L’ampère (A)","Le volt (V)","L’ohm (Ω)","Le joule (J)"]'::jsonb, 0, 'Elle mesure le débit de charges électriques.', 1),
    ('528e22bf-4f33-5f9e-b554-6bc2d7230dc8'::uuid, 'bd683e3d-650d-5e95-a5f2-8a9e51bd159c'::uuid, 'Comment se branche un ampèremètre ?', 'mcq', '["En série, de façon à être traversé par le courant","En dérivation aux bornes du dipôle","Aux bornes du générateur","Sur un fil coupé, sans le relier"]'::jsonb, 0, 'En dérivation, il créerait un court-circuit.', 2),
    ('8a0da805-e495-53cf-9071-2ccddf73aa63'::uuid, 'bd683e3d-650d-5e95-a5f2-8a9e51bd159c'::uuid, 'Que peut-on dire de l’intensité dans un circuit en série ?', 'mcq', '["Elle est la même en tout point","Elle diminue après chaque lampe","Elle s’additionne","Elle est nulle au retour"]'::jsonb, 0, 'L’ordre des dipôles n’a aucune influence.', 3),
    ('8f9e54b1-76cf-56e9-bc2a-6e4480b9ce4c'::uuid, 'bd683e3d-650d-5e95-a5f2-8a9e51bd159c'::uuid, 'Que dit la loi des nœuds dans un circuit en dérivation ?', 'mcq', '["L’intensité principale est la somme des intensités des branches","Toutes les branches ont la même intensité","L’intensité est nulle au nœud","L’intensité se divise toujours en deux parts égales"]'::jsonb, 0, 'Elle traduit la conservation de la charge.', 4),
    ('be89ce6f-79f3-54b1-8545-0b7bb5631931'::uuid, 'bd683e3d-650d-5e95-a5f2-8a9e51bd159c'::uuid, 'À combien d’ampères correspond 1 mA ?', 'mcq', '["0,001 A","0,1 A","10 A","1 000 A"]'::jsonb, 0, 'Le milliampère est le millième de l’ampère.', 5),
    ('115bfcec-c868-528a-ae22-0883aaf26cdd'::uuid, 'bd683e3d-650d-5e95-a5f2-8a9e51bd159c'::uuid, 'Sur quel calibre commence-t-on une mesure d’intensité ?', 'mcq', '["Sur le plus grand calibre, puis on descend","Sur le plus petit calibre","Peu importe le calibre","Sur le calibre du milieu"]'::jsonb, 0, 'Commencer trop bas risquerait d’endommager l’appareil.', 6),
    ('0333413b-d521-5d74-a916-5aaf12537657'::uuid, 'bd683e3d-650d-5e95-a5f2-8a9e51bd159c'::uuid, 'À quoi sert un fusible ?', 'mcq', '["À couper le circuit quand l’intensité dépasse une limite","À augmenter la tension","À stabiliser le courant","À mesurer l’intensité"]'::jsonb, 0, 'Il protège l’installation d’un incendie ; le disjoncteur joue le même rôle en se réarmant.', 7),
    ('2661cdc6-b646-58eb-962f-77e3d7c1ee8b'::uuid, 'bd683e3d-650d-5e95-a5f2-8a9e51bd159c'::uuid, 'Brancher plusieurs appareils sur une même multiprise augmente la tension reçue.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La tension reste 230 V ; ce sont les intensités qui s’additionnent.', 8),
    ('48b7c457-29fc-59a2-a81e-8949cb105f8c'::uuid, '1b2c92c6-40c5-5fdc-a164-74ee78306a1b'::uuid, 'Quelle est la formule de la loi d’Ohm ?', 'mcq', '["U = R × I","U = R ÷ I","R = U × I","I = R × U"]'::jsonb, 0, 'On en déduit R = U ÷ I et I = U ÷ R.', 1),
    ('5d00c4b5-2819-509b-b0b6-4cd3d1980120'::uuid, '1b2c92c6-40c5-5fdc-a164-74ee78306a1b'::uuid, 'Dans quelle unité se mesure une résistance ?', 'mcq', '["L’ohm (Ω)","Le volt (V)","L’ampère (A)","Le watt (W)"]'::jsonb, 0, 'Le symbole est la lettre grecque oméga.', 2),
    ('1ca40334-842b-52f8-ae37-7ef7dc60cfbe'::uuid, '1b2c92c6-40c5-5fdc-a164-74ee78306a1b'::uuid, 'Que devient l’intensité quand la résistance augmente, à tension constante ?', 'mcq', '["Elle diminue","Elle augmente","Elle reste identique","Elle s’annule brutalement"]'::jsonb, 0, 'I = U ÷ R : R au dénominateur.', 3),
    ('f9a2d381-0f87-51b0-bf3a-740d0f3ec933'::uuid, '1b2c92c6-40c5-5fdc-a164-74ee78306a1b'::uuid, 'Quelle est l’allure du graphique U en fonction de I pour un conducteur ohmique ?', 'mcq', '["Une droite passant par l’origine","Une parabole","Une droite ne passant pas par l’origine","Une courbe décroissante"]'::jsonb, 0, 'Sa pente vaut la résistance R.', 4),
    ('c2f5e0a0-b025-5366-9a4c-265fed952a33'::uuid, '1b2c92c6-40c5-5fdc-a164-74ee78306a1b'::uuid, 'Qu’est-ce que l’effet Joule ?', 'mcq', '["L’échauffement d’une résistance parcourue par un courant","La production de lumière par un courant","La création d’un champ magnétique","La chute de tension dans un générateur"]'::jsonb, 0, 'Recherché dans un radiateur, subi dans les fils.', 5),
    ('cbcaa40b-62e2-5d86-9c20-ac5ce24266d5'::uuid, '1b2c92c6-40c5-5fdc-a164-74ee78306a1b'::uuid, 'Dans quel appareil l’effet Joule est-il recherché ?', 'mcq', '["Un grille-pain","Un ordinateur portable","Un moteur électrique","Un transformateur"]'::jsonb, 0, 'Le chauffage y est justement la fonction attendue.', 6),
    ('c3c5c51c-62fc-5442-9308-2b4142ef4062'::uuid, '1b2c92c6-40c5-5fdc-a164-74ee78306a1b'::uuid, 'À quoi sert une résistance placée en série avec une LED ?', 'mcq', '["À limiter l’intensité pour ne pas la griller","À augmenter sa luminosité","À la protéger de l’humidité","À inverser le sens du courant"]'::jsonb, 0, 'C’est son usage le plus courant en électronique.', 7),
    ('98662849-3caa-537f-8dde-764b52bd2fab'::uuid, '1b2c92c6-40c5-5fdc-a164-74ee78306a1b'::uuid, 'La résistance d’un conducteur ohmique dépend de la tension qu’on lui applique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est constante : c’est justement ce que traduit la droite de la loi d’Ohm.', 8),
    ('4401017f-7c37-5680-9a5c-a0afbe13faca'::uuid, 'd29dd555-f284-587b-a4b6-ad636363deef'::uuid, 'Quelle est la formule de la puissance électrique ?', 'mcq', '["P = U × I","P = U ÷ I","P = I ÷ U","P = U + I"]'::jsonb, 0, 'La tension en volts multipliée par l’intensité en ampères.', 1),
    ('60495cf8-ba1e-5d0e-8a3d-d6469b1a416b'::uuid, 'd29dd555-f284-587b-a4b6-ad636363deef'::uuid, 'Dans quelle unité se mesure la puissance ?', 'mcq', '["Le watt (W)","Le joule (J)","Le volt (V)","L’ampère (A)"]'::jsonb, 0, 'Le joule est l’unité de l’énergie.', 2),
    ('4e2b09b7-dbce-57e8-acfc-81bc95f0df3a'::uuid, 'd29dd555-f284-587b-a4b6-ad636363deef'::uuid, 'Quelle est la formule de l’énergie électrique consommée ?', 'mcq', '["E = P × t","E = P ÷ t","E = U × I × R","E = t ÷ P"]'::jsonb, 0, 'En joules si t est en secondes, en wattheures si t est en heures.', 3),
    ('1be39cf1-e274-5ead-bde9-f1f3efe25779'::uuid, 'd29dd555-f284-587b-a4b6-ad636363deef'::uuid, 'À combien de joules correspond 1 kWh ?', 'mcq', '["3,6 × 10⁶ J","1 000 J","3 600 J","10⁵ J"]'::jsonb, 0, '1 000 W pendant 3 600 secondes.', 4),
    ('f5bda3e1-26ed-5ac6-94cf-ab0cf32c0f7a'::uuid, 'd29dd555-f284-587b-a4b6-ad636363deef'::uuid, 'Quelle intensité appelle un appareil de 2 000 W sous 230 V ?', 'mcq', '["Environ 8,7 A","Environ 0,1 A","Environ 87 A","Environ 2 A"]'::jsonb, 0, 'I = P ÷ U = 2 000 ÷ 230.', 5),
