    ('c57305c7-d094-5bd7-80c9-f3ebef4832e9'::uuid, 'd29dd555-f284-587b-a4b6-ad636363deef'::uuid, 'Quelle est la différence entre puissance et énergie ?', 'mcq', '["La puissance est la vitesse de consommation, l’énergie la quantité totale consommée","Ce sont deux mots pour la même grandeur","La puissance se mesure en joules","L’énergie ne dépend pas de la durée"]'::jsonb, 0, 'Une ampoule de 60 W une heure consomme autant qu’une de 6 W dix heures.', 7),
    ('b8b3d9ea-7a1a-5a85-a795-aa752f2d7cd5'::uuid, 'd29dd555-f284-587b-a4b6-ad636363deef'::uuid, 'Une ampoule LED de 8 W éclaire moins qu’une ampoule à filament de 60 W.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles éclairent autant : la LED convertit simplement une bien plus grande part de l’électricité en lumière.', 8),
    ('4c950254-0040-5642-9369-ff18e105ac02'::uuid, '9e11b9ff-61bd-5a6f-940d-cbe0b2276a5d'::uuid, 'Qu’est-ce qu’un signal ?', 'mcq', '["Un phénomène physique qui transporte une information sans transporter de matière","Un déplacement de matière d’un point à un autre","Une source d’énergie","Un appareil de mesure"]'::jsonb, 0, 'Émetteur, milieu de propagation, récepteur.', 1),
    ('a45acbda-2fbf-5bce-9c7c-06424ee446ab'::uuid, '9e11b9ff-61bd-5a6f-940d-cbe0b2276a5d'::uuid, 'Quel signal ne peut PAS se propager dans le vide ?', 'mcq', '["Le signal sonore","Le signal lumineux","Une onde radio","Le Wi-Fi"]'::jsonb, 0, 'Le son a besoin d’un milieu matériel.', 2),
    ('34c016bf-ed16-5a09-be27-025feba41fc3'::uuid, '9e11b9ff-61bd-5a6f-940d-cbe0b2276a5d'::uuid, 'À quelle vitesse se propagent les signaux lumineux dans le vide ?', 'mcq', '["Environ 300 000 km/s","Environ 340 m/s","Environ 3 000 km/s","Environ 1 500 m/s"]'::jsonb, 0, '340 m/s est la vitesse du son dans l’air.', 3),
    ('ea2d15cd-3515-56af-a85f-3831e402a418'::uuid, '9e11b9ff-61bd-5a6f-940d-cbe0b2276a5d'::uuid, 'Qu’est-ce qu’un signal numérique ?', 'mcq', '["Un signal codé par une suite de 0 et de 1","Un signal qui varie de façon continue","Un signal transporté par un fil uniquement","Un signal invisible"]'::jsonb, 0, 'Il résiste bien mieux aux perturbations qu’un signal analogique.', 4),
    ('220fd133-bc19-54b5-bc47-4ed9e4177683'::uuid, '9e11b9ff-61bd-5a6f-940d-cbe0b2276a5d'::uuid, 'Combien de bits contient un octet ?', 'mcq', '["8","10","4","16"]'::jsonb, 0, '1 ko vaut 1 000 octets.', 5),
    ('cf10eeb8-abd2-580a-b40d-d4e65d021f7c'::uuid, '9e11b9ff-61bd-5a6f-940d-cbe0b2276a5d'::uuid, 'Quel exemple correspond à un signal analogique ?', 'mcq', '["Le sillon d’un disque vinyle","Un fichier MP3","Une image JPEG","Un message texte"]'::jsonb, 0, 'Il varie de façon continue, sans codage en bits.', 6),
