    ('1795c214-061f-5630-ace2-7e8b8057bf80'::uuid, 'e0a19e09-b987-5025-bd20-6c4f00eeb94e'::uuid, 'Qu’est-ce qu’une source primaire de lumière ?', 'mcq', '["Un objet qui produit sa propre lumière","Un objet qui renvoie la lumière reçue","Un objet transparent","Un objet noir"]'::jsonb, 0, 'Le Soleil et une LED en sont ; la Lune n’en est pas une.', 1),
    ('a8bcc5be-6d8a-5f35-865d-1487564c6aa0'::uuid, 'e0a19e09-b987-5025-bd20-6c4f00eeb94e'::uuid, 'Comment se propage la lumière dans un milieu homogène et transparent ?', 'mcq', '["En ligne droite","En zigzag","En cercle","Elle ne se propage pas"]'::jsonb, 0, 'C’est ce qui explique les ombres et les éclipses.', 2),
    ('22174c3e-5c97-538b-8f5e-5103941f3d8b'::uuid, 'e0a19e09-b987-5025-bd20-6c4f00eeb94e'::uuid, 'Que fait un prisme à la lumière blanche ?', 'mcq', '["Il la disperse en un spectre continu de couleurs","Il l’absorbe entièrement","Il la transforme en son","Il l’accélère"]'::jsonb, 0, 'C’est le même phénomène que dans un arc-en-ciel.', 3),
    ('a0314e16-933f-52a2-8f6b-cccde154f2e3'::uuid, 'e0a19e09-b987-5025-bd20-6c4f00eeb94e'::uuid, 'De quelle couleur apparaît un objet rouge éclairé en lumière verte ?', 'mcq', '["Noir","Rouge","Vert","Jaune"]'::jsonb, 0, 'Il n’a aucune lumière rouge à diffuser.', 4),
    ('32c8842c-242f-59fb-9c5d-092bccd2fef5'::uuid, 'e0a19e09-b987-5025-bd20-6c4f00eeb94e'::uuid, 'Quelles sont les trois couleurs primaires de la synthèse additive ?', 'mcq', '["Rouge, vert, bleu","Rouge, jaune, bleu","Cyan, magenta, jaune","Blanc, noir, gris"]'::jsonb, 0, 'C’est le système RVB des écrans.', 5),
    ('bd7bae28-a794-5966-ba30-d487547a4f64'::uuid, 'e0a19e09-b987-5025-bd20-6c4f00eeb94e'::uuid, 'Que donne le mélange des trois couleurs primaires en synthèse additive ?', 'mcq', '["Du blanc","Du noir","Du gris","Du marron"]'::jsonb, 0, 'C’est ainsi qu’un écran produit du blanc.', 6),
    ('41a38899-0488-58c2-bcde-0d1aa7fa9b8f'::uuid, 'e0a19e09-b987-5025-bd20-6c4f00eeb94e'::uuid, 'Pourquoi voit-on un objet non lumineux ?', 'mcq', '["Parce qu’il diffuse vers notre œil la lumière qu’il reçoit","Parce qu’il produit de la lumière","Parce que notre œil émet de la lumière","Parce qu’il absorbe toute la lumière"]'::jsonb, 0, 'Sans lumière parvenant à l’œil, aucun objet n’est visible.', 7),
    ('2bcb39a3-3650-53f9-a39b-ebc865b8ffcd'::uuid, 'e0a19e09-b987-5025-bd20-6c4f00eeb94e'::uuid, 'La lumière blanche est une couleur simple, non décomposable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le prisme montre qu’elle est composée de toutes les couleurs du spectre.', 8),
    ('6a6e08fa-dd11-58aa-bb1e-9c88973ede08'::uuid, '1b8b8546-2565-55c6-ba12-7a419b5d728b'::uuid, 'Qu’est-ce qui produit un son ?', 'mcq', '["Un objet qui vibre","Un objet qui chauffe","Un objet qui brille","Un objet immobile"]'::jsonb, 0, 'Corde, membrane ou colonne d’air en vibration.', 1),
    ('c0471ce4-705f-51fd-abc5-2fda7dc1caf5'::uuid, '1b8b8546-2565-55c6-ba12-7a419b5d728b'::uuid, 'Le son peut-il se propager dans le vide ?', 'mcq', '["Non, il a besoin d’un milieu matériel","Oui, comme la lumière","Oui, mais plus lentement","Seulement s’il est très fort"]'::jsonb, 0, 'L’expérience de la cloche à vide le démontre.', 2),
    ('c44e8f01-4686-51b4-8672-127c173c8b08'::uuid, '1b8b8546-2565-55c6-ba12-7a419b5d728b'::uuid, 'Quelle est la vitesse du son dans l’air ?', 'mcq', '["Environ 340 m/s","Environ 300 000 km/s","Environ 1 500 m/s","Environ 34 m/s"]'::jsonb, 0, '1 500 m/s est sa vitesse dans l’eau.', 3),
    ('bba80480-0ece-5275-9a76-78fbe6fc5e75'::uuid, '1b8b8546-2565-55c6-ba12-7a419b5d728b'::uuid, 'Que mesure la fréquence d’un son ?', 'mcq', '["Sa hauteur : grave ou aigu","Son volume","Sa vitesse de propagation","Sa durée"]'::jsonb, 0, 'Elle s’exprime en hertz (Hz).', 4),
    ('4be6b41a-5876-589b-b838-259473ea63bb'::uuid, '1b8b8546-2565-55c6-ba12-7a419b5d728b'::uuid, 'Quel est le domaine des fréquences audibles par l’oreille humaine ?', 'mcq', '["Environ 20 Hz à 20 000 Hz","0 Hz à 100 Hz","100 Hz à 1 000 Hz","20 000 Hz à 50 000 Hz"]'::jsonb, 0, 'En dessous ce sont des infrasons, au-dessus des ultrasons.', 5),
    ('202f1974-bac1-5dcf-93a4-25f4b11547b4'::uuid, '1b8b8546-2565-55c6-ba12-7a419b5d728b'::uuid, 'Dans quelle unité mesure-t-on le niveau sonore ?', 'mcq', '["Le décibel (dB)","Le hertz (Hz)","Le watt (W)","Le mètre par seconde (m/s)"]'::jsonb, 0, 'Le hertz mesure la fréquence, pas le volume.', 6),
    ('8e6ccb29-02d8-5621-96a8-3a9a45953d14'::uuid, '1b8b8546-2565-55c6-ba12-7a419b5d728b'::uuid, 'À partir de quel niveau sonore une exposition prolongée devient-elle dangereuse ?', 'mcq', '["85 dB","30 dB","120 dB seulement","200 dB"]'::jsonb, 0, '120 dB est le seuil de douleur, mais le danger commence bien avant.', 7),
    ('748cdf16-ae8d-58a5-a7c3-4c1b58c5174f'::uuid, '1b8b8546-2565-55c6-ba12-7a419b5d728b'::uuid, 'Les cellules de l’oreille interne détruites par le bruit peuvent se régénérer.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les dommages sont définitifs : la prévention est la seule protection.', 8),
    ('498cdd52-611e-5c09-b35f-c47af5bbf411'::uuid, '0a5510c5-38df-57c7-84c2-07feb5862f56'::uuid, 'Que fait un microphone ?', 'mcq', '["Il convertit une vibration de l’air en signal électrique","Il amplifie le son sans le transformer","Il produit un son pur","Il mesure la fréquence directement"]'::jsonb, 0, 'L’oscilloscope trace ensuite ce signal en fonction du temps.', 1),
    ('78ef1996-ee50-50b0-8e1a-0a1258e4ee74'::uuid, '0a5510c5-38df-57c7-84c2-07feb5862f56'::uuid, 'Quelle courbe correspond à un son pur ?', 'mcq', '["Une sinusoïde régulière","Une courbe sans période","Une droite horizontale","Une courbe en escalier"]'::jsonb, 0, 'C’est le signal d’un diapason.', 2),
    ('dcfa4168-b6ee-5783-bf73-5595aad3d145'::uuid, '0a5510c5-38df-57c7-84c2-07feb5862f56'::uuid, 'Quelle est la relation entre fréquence et période ?', 'mcq', '["f = 1 ÷ T","f = T","f = T × 2","f = T ÷ 2"]'::jsonb, 0, 'Une période courte donne une fréquence élevée.', 3),
    ('a407a9e0-f230-5942-acac-137806336698'::uuid, '0a5510c5-38df-57c7-84c2-07feb5862f56'::uuid, 'Quelle est la fréquence d’un son de période 4 ms ?', 'mcq', '["250 Hz","4 Hz","400 Hz","25 Hz"]'::jsonb, 0, 'f = 1 ÷ 0,004 s.', 4),
    ('b44a2bea-c3fb-56a4-b8b0-e557bcdc5a78'::uuid, '0a5510c5-38df-57c7-84c2-07feb5862f56'::uuid, 'Que traduit l’amplitude d’un signal sonore ?', 'mcq', '["L’intensité du son : fort ou faible","La hauteur du son : grave ou aigu","La vitesse du son","La durée du son"]'::jsonb, 0, 'La fréquence, elle, donne la hauteur.', 5),
    ('5f3358ff-c1d3-5091-9d9c-9a6974220d71'::uuid, '0a5510c5-38df-57c7-84c2-07feb5862f56'::uuid, 'Comment appelle-t-on les sons de fréquence supérieure à 20 000 Hz ?', 'mcq', '["Les ultrasons","Les infrasons","Les sons purs","Les harmoniques"]'::jsonb, 0, 'Chauves-souris, sonars et échographies les utilisent.', 6),
    ('eb8f40a0-6fad-5aca-abbb-05c4a4ac74c5'::uuid, '0a5510c5-38df-57c7-84c2-07feb5862f56'::uuid, 'Quelle courbe correspond à un bruit ?', 'mcq', '["Une courbe sans période identifiable","Une sinusoïde parfaite","Une courbe périodique complexe","Une droite"]'::jsonb, 0, 'C’est ce qui le distingue d’une note de musique.', 7),
    ('4db40276-f73c-5d86-8b1e-9dbd6cf257a8'::uuid, '0a5510c5-38df-57c7-84c2-07feb5862f56'::uuid, 'Augmenter l’amplitude d’un son le rend plus aigu.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Cela le rend plus fort : la hauteur ne dépend que de la fréquence.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('physique-chimie');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('physique-chimie')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 295 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 295 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
